insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('05537578-f36d-5387-823f-005c1d5ba1cb', '5cb5e738-220a-4267-901a-841c834b5d56', '1', '‏ ‏حَدَّثَنَا ‏ ‏الْحُمَيْدِيُّ عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأَنْصَارِيُّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ التَّيْمِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَلْقَمَةَ بْنَ وَقَّاصٍ اللَّيْثِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّمَا الْأَعْمَالُ ‏ ‏بِالنِّيَّاتِ ‏ ‏وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا ‏ ‏يُصِيبُهَا ‏ ‏أَوْ إِلَى امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f035e33e-1e3b-5ff7-aedf-dd3ff2a02ebc', '5cb5e738-220a-4267-901a-841c834b5d56', '2', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَنَّ ‏ ‏الْحَارِثَ بْنَ هِشَامٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ كَيْفَ يَأْتِيكَ الْوَحْيُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْيَانًا يَأْتِينِي مِثْلَ ‏ ‏صَلْصَلَةِ ‏ ‏الْجَرَسِ وَهُوَ أَشَدُّهُ عَلَيَّ ‏ ‏فَيُفْصَمُ ‏ ‏عَنِّي وَقَدْ وَعَيْتُ عَنْهُ مَا قَالَ وَأَحْيَانًا يَتَمَثَّلُ لِي ‏ ‏الْمَلَكُ ‏ ‏رَجُلًا فَيُكَلِّمُنِي فَأَعِي مَا يَقُولُ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏وَلَقَدْ رَأَيْتُهُ يَنْزِلُ عَلَيْهِ الْوَحْيُ فِي الْيَوْمِ الشَّدِيدِ الْبَرْدِ ‏ ‏فَيَفْصِمُ ‏ ‏عَنْهُ وَإِنَّ جَبِينَهُ ‏ ‏لَيَتَفَصَّدُ ‏ ‏عَرَقًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('749a3142-b2c5-511e-b60e-08018a72d097', '5cb5e738-220a-4267-901a-841c834b5d56', '3', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْوَحْيِ الرُّؤْيَا الصَّالِحَةُ فِي النَّوْمِ فَكَانَ لَا يَرَى رُؤْيَا إِلَّا جَاءَتْ مِثْلَ ‏ ‏فَلَقِ ‏ ‏الصُّبْحِ ثُمَّ حُبِّبَ إِلَيْهِ الْخَلَاءُ وَكَانَ يَخْلُو ‏ ‏بِغَارِ حِرَاءٍ ‏ ‏فَيَتَحَنَّثُ ‏ ‏فِيهِ ‏ ‏وَهُوَ التَّعَبُّدُ ‏ ‏اللَّيَالِيَ ذَوَاتِ الْعَدَدِ ‏ ‏قَبْلَ أَنْ ‏ ‏يَنْزِعَ ‏ ‏إِلَى أَهْلِهِ وَيَتَزَوَّدُ لِذَلِكَ ثُمَّ يَرْجِعُ إِلَى ‏ ‏خَدِيجَةَ ‏ ‏فَيَتَزَوَّدُ لِمِثْلِهَا حَتَّى جَاءَهُ الْحَقُّ وَهُوَ فِي ‏ ‏غَارِ حِرَاءٍ ‏ ‏فَجَاءَهُ ‏ ‏الْمَلَكُ ‏ ‏فَقَالَ ‏ ‏اقْرَأْ قَالَ مَا أَنَا بِقَارِئٍ قَالَ فَأَخَذَنِي ‏ ‏فَغَطَّنِي ‏ ‏حَتَّى بَلَغَ مِنِّي الْجَهْدَ ثُمَّ ‏ ‏أَرْسَلَنِي ‏ ‏فَقَالَ اقْرَأْ قُلْتُ مَا أَنَا بِقَارِئٍ فَأَخَذَنِي ‏ ‏فَغَطَّنِي ‏ ‏الثَّانِيَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدَ ثُمَّ ‏ ‏أَرْسَلَنِي ‏ ‏فَقَالَ اقْرَأْ فَقُلْتُ مَا أَنَا بِقَارِئٍ فَأَخَذَنِي ‏ ‏فَغَطَّنِي ‏ ‏الثَّالِثَةَ ثُمَّ ‏ ‏أَرْسَلَنِي ‏ ‏فَقَالَ ‏ { ‏اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ خَلَقَ الْإِنْسَانَ مِنْ ‏ ‏عَلَقٍ ‏ ‏اقْرَأْ وَرَبُّكَ الْأَكْرَمُ ‏} ‏فَرَجَعَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْجُفُ فُؤَادُهُ فَدَخَلَ عَلَى ‏ ‏خَدِيجَةَ بِنْتِ خُوَيْلِدٍ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَقَالَ ‏ ‏زَمِّلُونِي ‏ ‏زَمِّلُونِي ‏ ‏فَزَمَّلُوهُ حَتَّى ذَهَبَ عَنْهُ ‏ ‏الرَّوْعُ ‏ ‏فَقَالَ ‏ ‏لِخَدِيجَةَ ‏ ‏وَأَخْبَرَهَا الْخَبَرَ لَقَدْ خَشِيتُ عَلَى نَفْسِي فَقَالَتْ ‏ ‏خَدِيجَةُ ‏ ‏كَلَّا وَاللَّهِ ‏ ‏مَا يُخْزِيكَ ‏ ‏اللَّهُ أَبَدًا إِنَّكَ لَتَصِلُ الرَّحِمَ وَتَحْمِلُ ‏ ‏الْكَلَّ ‏ ‏وَتَكْسِبُ ‏ ‏الْمَعْدُومَ ‏ ‏وَتَقْرِي ‏ ‏الضَّيْفَ وَتُعِينُ عَلَى ‏ ‏نَوَائِبِ ‏ ‏الْحَقِّ فَانْطَلَقَتْ بِهِ ‏ ‏خَدِيجَةُ ‏ ‏حَتَّى أَتَتْ بِهِ ‏ ‏وَرَقَةَ بْنَ نَوْفَلِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى ‏ ‏ابْنَ عَمِّ ‏ ‏خَدِيجَةَ ‏ ‏وَكَانَ امْرَأً قَدْ ‏ ‏تَنَصَّرَ ‏ ‏فِي الْجَاهِلِيَّةِ وَكَانَ يَكْتُبُ الْكِتَابَ الْعِبْرَانِيَّ فَيَكْتُبُ مِنْ الْإِنْجِيلِ بِالْعِبْرَانِيَّةِ مَا شَاءَ اللَّهُ أَنْ يَكْتُبَ وَكَانَ شَيْخًا كَبِيرًا قَدْ عَمِيَ فَقَالَتْ لَهُ ‏ ‏خَدِيجَةُ ‏ ‏يَا ابْنَ عَمِّ اسْمَعْ مِنْ ابْنِ أَخِيكَ فَقَالَ لَهُ ‏ ‏وَرَقَةُ ‏ ‏يَا ابْنَ أَخِي مَاذَا تَرَى فَأَخْبَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَبَرَ مَا رَأَى فَقَالَ لَهُ ‏ ‏وَرَقَةُ ‏ ‏هَذَا ‏ ‏النَّامُوسُ ‏ ‏الَّذِي نَزَّلَ اللَّهُ عَلَى ‏ ‏مُوسَى ‏ ‏يَا لَيْتَنِي فِيهَا جَذَعًا لَيْتَنِي أَكُونُ حَيًّا إِذْ يُخْرِجُكَ قَوْمُكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَمُخْرِجِيَّ هُمْ قَالَ نَعَمْ لَمْ يَأْتِ رَجُلٌ قَطُّ بِمِثْلِ مَا جِئْتَ بِهِ إِلَّا عُودِيَ وَإِنْ يُدْرِكْنِي يَوْمُكَ أَنْصُرْكَ نَصْرًا ‏ ‏مُؤَزَّرًا ‏ ‏ثُمَّ لَمْ ‏ ‏يَنْشَبْ ‏ ‏وَرَقَةُ ‏ ‏أَنْ تُوُفِّيَ وَفَتَرَ الْوَحْيُ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ الْأَنْصَارِيَّ ‏ ‏قَالَ ‏ ‏وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْيِ فَقَالَ فِي حَدِيثِهِ بَيْنَا أَنَا أَمْشِي إِذْ سَمِعْتُ صَوْتًا مِنْ السَّمَاءِ فَرَفَعْتُ بَصَرِي فَإِذَا ‏ ‏الْمَلَكُ ‏ ‏الَّذِي جَاءَنِي ‏ ‏بِحِرَاءٍ ‏ ‏جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالْأَرْضِ فَرُعِبْتُ مِنْهُ فَرَجَعْتُ فَقُلْتُ ‏ ‏زَمِّلُونِي ‏ ‏زَمِّلُونِي فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏يَا أَيُّهَا ‏ ‏الْمُدَّثِّرُ ‏ ‏قُمْ فَأَنْذِرْ ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَالرُّجْزَ ‏ ‏فَاهْجُرْ ‏} ‏فَحَمِيَ ‏ ‏الْوَحْيُ وَتَتَابَعَ ‏ ‏تَابَعَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏وَأَبُو صَالِحٍ ‏ ‏وَتَابَعَهُ ‏ ‏هِلَالُ بْنُ رَدَّادٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏وَمَعْمَرٌ ‏ ‏بَوَادِرُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('61021e5e-93aa-584c-8ae3-7c97fec9f163', '5cb5e738-220a-4267-901a-841c834b5d56', '4', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ أَبِي عَائِشَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ تَعَالَى ‏ { ‏لَا تُحَرِّكْ بِهِ لِسَانَكَ ‏ ‏لِتَعْجَلَ بِهِ ‏ } ‏قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَالِجُ ‏ ‏مِنْ التَّنْزِيلِ شِدَّةً وَكَانَ مِمَّا يُحَرِّكُ شَفَتَيْهِ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَأَنَا أُحَرِّكُهُمَا لَكُمْ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَرِّكُهُمَا وَقَالَ ‏ ‏سَعِيدٌ ‏ ‏أَنَا أُحَرِّكُهُمَا كَمَا رَأَيْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يُحَرِّكُهُمَا فَحَرَّكَ شَفَتَيْهِ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏لَا تُحَرِّكْ بِهِ لِسَانَكَ ‏ ‏لِتَعْجَلَ بِهِ ‏ ‏إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْآنَهُ ‏} ‏قَالَ جَمْعُهُ لَكَ فِي صَدْرِكَ وَتَقْرَأَهُ ‏ { ‏فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ ‏} ‏قَالَ فَاسْتَمِعْ لَهُ وَأَنْصِتْ ‏ { ‏ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُ ‏} ‏ثُمَّ إِنَّ عَلَيْنَا أَنْ تَقْرَأَهُ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ ذَلِكَ إِذَا أَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏اسْتَمَعَ فَإِذَا انْطَلَقَ ‏ ‏جِبْرِيلُ ‏ ‏قَرَأَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا قَرَأَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3da77a75-761f-5627-97b6-0f7090111aa6', '5cb5e738-220a-4267-901a-841c834b5d56', '5', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدَانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏بِشْرُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏وَمَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏نَحْوَهُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجْوَدَ النَّاسِ وَكَانَ أَجْوَدُ مَا يَكُونُ فِي رَمَضَانَ حِينَ يَلْقَاهُ ‏ ‏جِبْرِيلُ ‏ ‏وَكَانَ يَلْقَاهُ فِي كُلِّ لَيْلَةٍ مِنْ رَمَضَانَ فَيُدَارِسُهُ الْقُرْآنَ فَلَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجْوَدُ بِالْخَيْرِ مِنْ الرِّيحِ ‏ ‏الْمُرْسَلَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d132b367-c321-524b-b76b-46daebb2cf61', '5cb5e738-220a-4267-901a-841c834b5d56', '6', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا سُفْيَانَ بْنَ حَرْبٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏هِرَقْلَ ‏ ‏أَرْسَلَ إِلَيْهِ فِي ‏ ‏رَكْبٍ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏وَكَانُوا تِجَارًا ‏ ‏بِالشَّأْمِ ‏ ‏فِي الْمُدَّةِ الَّتِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَادَّ ‏ ‏فِيهَا ‏ ‏أَبَا سُفْيَانَ ‏ ‏وَكُفَّارَ ‏ ‏قُرَيْشٍ ‏ ‏فَأَتَوْهُ وَهُمْ ‏ ‏بِإِيلِيَاءَ ‏ ‏فَدَعَاهُمْ فِي مَجْلِسِهِ وَحَوْلَهُ عُظَمَاءُ ‏ ‏الرُّومِ ‏ ‏ثُمَّ دَعَاهُمْ وَدَعَا بِتَرْجُمَانِهِ فَقَالَ أَيُّكُمْ أَقْرَبُ نَسَبًا بِهَذَا الرَّجُلِ الَّذِي يَزْعُمُ أَنَّهُ نَبِيٌّ فَقَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏فَقُلْتُ أَنَا أَقْرَبُهُمْ نَسَبًا فَقَالَ أَدْنُوهُ مِنِّي وَقَرِّبُوا أَصْحَابَهُ فَاجْعَلُوهُمْ عِنْدَ ظَهْرِهِ ثُمَّ قَالَ لِتَرْجُمَانِهِ قُلْ لَهُمْ إِنِّي سَائِلٌ هَذَا عَنْ هَذَا الرَّجُلِ فَإِنْ كَذَبَنِي فَكَذِّبُوهُ فَوَاللَّهِ لَوْلَا الْحَيَاءُ مِنْ أَنْ ‏ ‏يَأْثِرُوا ‏ ‏عَلَيَّ كَذِبًا لَكَذَبْتُ عَنْهُ ثُمَّ كَانَ أَوَّلَ مَا سَأَلَنِي عَنْهُ أَنْ قَالَ كَيْفَ نَسَبُهُ فِيكُمْ قُلْتُ هُوَ فِينَا ذُو نَسَبٍ قَالَ فَهَلْ قَالَ هَذَا الْقَوْلَ مِنْكُمْ أَحَدٌ قَطُّ قَبْلَهُ قُلْتُ لَا قَالَ فَهَلْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ قُلْتُ لَا قَالَ فَأَشْرَافُ النَّاسِ يَتَّبِعُونَهُ أَمْ ضُعَفَاؤُهُمْ فَقُلْتُ بَلْ ضُعَفَاؤُهُمْ قَالَ أَيَزِيدُونَ أَمْ يَنْقُصُونَ قُلْتُ بَلْ يَزِيدُونَ قَالَ فَهَلْ يَرْتَدُّ أَحَدٌ مِنْهُمْ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ قُلْتُ لَا قَالَ فَهَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ قُلْتُ لَا قَالَ فَهَلْ يَغْدِرُ قُلْتُ لَا وَنَحْنُ مِنْهُ فِي مُدَّةٍ لَا نَدْرِي مَا هُوَ فَاعِلٌ فِيهَا قَالَ وَلَمْ تُمْكِنِّي كَلِمَةٌ أُدْخِلُ فِيهَا شَيْئًا غَيْرُ هَذِهِ الْكَلِمَةِ قَالَ فَهَلْ قَاتَلْتُمُوهُ قُلْتُ نَعَمْ قَالَ فَكَيْفَ كَانَ قِتَالُكُمْ إِيَّاهُ قُلْتُ الْحَرْبُ بَيْنَنَا وَبَيْنَهُ ‏ ‏سِجَالٌ ‏ ‏يَنَالُ مِنَّا وَنَنَالُ مِنْهُ قَالَ مَاذَا يَأْمُرُكُمْ قُلْتُ يَقُولُ اعْبُدُوا اللَّهَ وَحْدَهُ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَاتْرُكُوا مَا يَقُولُ آبَاؤُكُمْ وَيَأْمُرُنَا بِالصَّلَاةِ وَالزَّكَاةِ وَالصِّدْقِ ‏ ‏وَالْعَفَافِ ‏ ‏وَالصِّلَةِ فَقَالَ لِلتَّرْجُمَانِ قُلْ لَهُ سَأَلْتُكَ عَنْ نَسَبِهِ فَذَكَرْتَ أَنَّهُ فِيكُمْ ذُو نَسَبٍ فَكَذَلِكَ الرُّسُلُ تُبْعَثُ فِي نَسَبِ قَوْمِهَا وَسَأَلْتُكَ هَلْ قَالَ أَحَدٌ مِنْكُمْ هَذَا الْقَوْلَ فَذَكَرْتَ أَنْ لَا فَقُلْتُ لَوْ كَانَ أَحَدٌ قَالَ هَذَا الْقَوْلَ قَبْلَهُ لَقُلْتُ رَجُلٌ ‏ ‏يَأْتَسِي ‏ ‏بِقَوْلٍ قِيلَ قَبْلَهُ وَسَأَلْتُكَ هَلْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ فَذَكَرْتَ أَنْ لَا قُلْتُ فَلَوْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ قُلْتُ رَجُلٌ يَطْلُبُ مُلْكَ أَبِيهِ وَسَأَلْتُكَ هَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ فَذَكَرْتَ أَنْ لَا فَقَدْ أَعْرِفُ أَنَّهُ لَمْ يَكُنْ ‏ ‏لِيَذَرَ ‏ ‏الْكَذِبَ عَلَى النَّاسِ وَيَكْذِبَ عَلَى اللَّهِ وَسَأَلْتُكَ أَشْرَافُ النَّاسِ اتَّبَعُوهُ أَمْ ضُعَفَاؤُهُمْ فَذَكَرْتَ أَنَّ ضُعَفَاءَهُمْ اتَّبَعُوهُ وَهُمْ أَتْبَاعُ الرُّسُلِ وَسَأَلْتُكَ أَيَزِيدُونَ أَمْ يَنْقُصُونَ فَذَكَرْتَ أَنَّهُمْ يَزِيدُونَ وَكَذَلِكَ أَمْرُ الْإِيمَانِ حَتَّى يَتِمَّ وَسَأَلْتُكَ أَيَرْتَدُّ أَحَدٌ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ فَذَكَرْتَ أَنْ لَا وَكَذَلِكَ الْإِيمَانُ حِينَ تُخَالِطُ بَشَاشَتُهُ الْقُلُوبَ وَسَأَلْتُكَ هَلْ يَغْدِرُ فَذَكَرْتَ أَنْ لَا وَكَذَلِكَ الرُّسُلُ لَا تَغْدِرُ وَسَأَلْتُكَ بِمَا يَأْمُرُكُمْ فَذَكَرْتَ أَنَّهُ يَأْمُرُكُمْ أَنْ تَعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَيَنْهَاكُمْ عَنْ عِبَادَةِ الْأَوْثَانِ وَيَأْمُرُكُمْ بِالصَّلَاةِ وَالصِّدْقِ ‏ ‏وَالْعَفَافِ ‏ ‏فَإِنْ كَانَ مَا تَقُولُ حَقًّا فَسَيَمْلِكُ مَوْضِعَ قَدَمَيَّ هَاتَيْنِ وَقَدْ كُنْتُ أَعْلَمُ أَنَّهُ خَارِجٌ لَمْ أَكُنْ أَظُنُّ أَنَّهُ مِنْكُمْ فَلَوْ أَنِّي أَعْلَمُ أَنِّي أَخْلُصُ إِلَيْهِ ‏ ‏لَتَجَشَّمْتُ ‏ ‏لِقَاءَهُ وَلَوْ كُنْتُ عِنْدَهُ لَغَسَلْتُ عَنْ قَدَمِهِ ثُمَّ دَعَا بِكِتَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي بَعَثَ بِهِ ‏ ‏دِحْيَةُ ‏ ‏إِلَى عَظِيمِ ‏ ‏بُصْرَى ‏ ‏فَدَفَعَهُ إِلَى ‏ ‏هِرَقْلَ ‏ ‏فَقَرَأَهُ فَإِذَا فِيهِ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَبْدِ اللَّهِ وَرَسُولِهِ إِلَى ‏ ‏هِرَقْلَ ‏ ‏عَظِيمِ ‏ ‏الرُّومِ ‏ ‏سَلَامٌ عَلَى مَنْ اتَّبَعَ الْهُدَى أَمَّا بَعْدُ فَإِنِّي أَدْعُوكَ ‏ ‏بِدِعَايَةِ ‏ ‏الْإِسْلَامِ أَسْلِمْ تَسْلَمْ يُؤْتِكَ اللَّهُ أَجْرَكَ مَرَّتَيْنِ فَإِنْ ‏ ‏تَوَلَّيْتَ ‏ ‏فَإِنَّ عَلَيْكَ إِثْمَ ‏ ‏الْأَرِيسِيِّينَ ‏ ‏وَ ‏ { ‏يَا ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَنْ لَا نَعْبُدَ إِلَّا اللَّهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللَّهِ فَإِنْ تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ ‏} ‏قَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏فَلَمَّا قَالَ مَا قَالَ وَفَرَغَ مِنْ قِرَاءَةِ الْكِتَابِ كَثُرَ عِنْدَهُ ‏ ‏الصَّخَبُ ‏ ‏وَارْتَفَعَتْ الْأَصْوَاتُ وَأُخْرِجْنَا فَقُلْتُ لِأَصْحَابِي حِينَ أُخْرِجْنَا لَقَدْ أَمِرَ أَمْرُ ‏ ‏ابْنِ أَبِي كَبْشَةَ ‏ ‏إِنَّهُ يَخَافُهُ مَلِكُ ‏ ‏بَنِي الْأَصْفَرِ ‏ ‏فَمَا زِلْتُ مُوقِنًا أَنَّهُ سَيَظْهَرُ حَتَّى أَدْخَلَ اللَّهُ عَلَيَّ الْإِسْلَامَ وَكَانَ ‏ ‏ابْنُ النَّاظُورِ ‏ ‏صَاحِبُ ‏ ‏إِيلِيَاءَ ‏ ‏وَهِرَقْلَ ‏ ‏سُقُفًّا ‏ ‏عَلَى ‏ ‏نَصَارَى ‏ ‏الشَّأْمِ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏هِرَقْلَ ‏ ‏حِينَ قَدِمَ ‏ ‏إِيلِيَاءَ ‏ ‏أَصْبَحَ يَوْمًا ‏ ‏خَبِيثَ النَّفْسِ ‏ ‏فَقَالَ بَعْضُ ‏ ‏بَطَارِقَتِهِ ‏ ‏قَدْ اسْتَنْكَرْنَا هَيْئَتَكَ قَالَ ‏ ‏ابْنُ النَّاظُورِ ‏ ‏وَكَانَ ‏ ‏هِرَقْلُ ‏ ‏حَزَّاءً ‏ ‏يَنْظُرُ فِي النُّجُومِ فَقَالَ لَهُمْ حِينَ سَأَلُوهُ إِنِّي رَأَيْتُ اللَّيْلَةَ حِينَ نَظَرْتُ فِي النُّجُومِ مَلِكَ الْخِتَانِ قَدْ ظَهَرَ فَمَنْ يَخْتَتِنُ مِنْ هَذِهِ الْأُمَّةِ قَالُوا لَيْسَ يَخْتَتِنُ إِلَّا ‏ ‏الْيَهُودُ ‏ ‏فَلَا يُهِمَّنَّكَ شَأْنُهُمْ وَاكْتُبْ إِلَى ‏ ‏مَدَايِنِ مُلْكِكَ فَيَقْتُلُوا مَنْ فِيهِمْ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَبَيْنَمَا هُمْ عَلَى أَمْرِهِمْ أُتِيَ ‏ ‏هِرَقْلُ ‏ ‏بِرَجُلٍ أَرْسَلَ بِهِ مَلِكُ ‏ ‏غَسَّانَ ‏ ‏يُخْبِرُ عَنْ خَبَرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا اسْتَخْبَرَهُ ‏ ‏هِرَقْلُ ‏ ‏قَالَ اذْهَبُوا فَانْظُرُوا أَمُخْتَتِنٌ هُوَ أَمْ لَا فَنَظَرُوا إِلَيْهِ فَحَدَّثُوهُ أَنَّهُ مُخْتَتِنٌ وَسَأَلَهُ عَنْ ‏ ‏الْعَرَبِ ‏ ‏فَقَالَ هُمْ يَخْتَتِنُونَ فَقَالَ ‏ ‏هِرَقْلُ ‏ ‏هَذَا مُلْكُ هَذِهِ الْأُمَّةِ قَدْ ‏ ‏ظَهَرَ ‏ ‏ثُمَّ كَتَبَ ‏ ‏هِرَقْلُ ‏ ‏إِلَى صَاحِبٍ لَهُ ‏ ‏بِرُومِيَةَ ‏ ‏وَكَانَ نَظِيرَهُ فِي الْعِلْمِ وَسَارَ ‏ ‏هِرَقْلُ ‏ ‏إِلَى ‏ ‏حِمْصَ ‏ ‏فَلَمْ يَرِمْ ‏ ‏حِمْصَ ‏ ‏حَتَّى أَتَاهُ كِتَابٌ مِنْ صَاحِبِهِ يُوَافِقُ رَأْيَ ‏ ‏هِرَقْلَ ‏ ‏عَلَى خُرُوجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَّهُ نَبِيٌّ فَأَذِنَ ‏ ‏هِرَقْلُ ‏ ‏لِعُظَمَاءِ ‏ ‏الرُّومِ ‏ ‏فِي ‏ ‏دَسْكَرَةٍ ‏ ‏لَهُ ‏ ‏بِحِمْصَ ‏ ‏ثُمَّ أَمَرَ بِأَبْوَابِهَا فَغُلِّقَتْ ثُمَّ اطَّلَعَ فَقَالَ يَا مَعْشَرَ ‏ ‏الرُّومِ ‏ ‏هَلْ لَكُمْ فِي الْفَلَاحِ وَالرُّشْدِ وَأَنْ يَثْبُتَ مُلْكُكُمْ فَتُبَايِعُوا هَذَا النَّبِيَّ ‏ ‏فَحَاصُوا ‏ ‏حَيْصَةَ حُمُرِ الْوَحْشِ إِلَى الْأَبْوَابِ فَوَجَدُوهَا قَدْ غُلِّقَتْ فَلَمَّا رَأَى ‏ ‏هِرَقْلُ ‏ ‏نَفْرَتَهُمْ وَأَيِسَ مِنْ الْإِيمَانِ قَالَ رُدُّوهُمْ عَلَيَّ وَقَالَ إِنِّي قُلْتُ مَقَالَتِي ‏ ‏آنِفًا ‏ ‏أَخْتَبِرُ بِهَا شِدَّتَكُمْ عَلَى دِينِكُمْ فَقَدْ رَأَيْتُ فَسَجَدُوا لَهُ وَرَضُوا عَنْهُ فَكَانَ ذَلِكَ آخِرَ شَأْنِ ‏ ‏هِرَقْلَ ‏ ‏رَوَاهُ ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏وَيُونُسُ ‏ ‏وَمَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9c15c968-d966-5c8d-977e-8b5c445bdf71', '5cb5e738-220a-4267-901a-841c834b5d56', '7', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَنْظَلَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالْحَجِّ وَصَوْمِ رَمَضَانَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b5bbef4c-8564-5787-9083-33834ff4a007', '5cb5e738-220a-4267-901a-841c834b5d56', '8', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ الْجُعْفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ الْعَقَدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِيمَانُ ‏ ‏بِضْعٌ ‏ ‏وَسِتُّونَ ‏ ‏شُعْبَةً ‏ ‏وَالْحَيَاءُ ‏ ‏شُعْبَةٌ ‏ ‏مِنْ الْإِيمَانِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0a6f9684-009a-5a14-92b8-ed855445b3bf', '5cb5e738-220a-4267-901a-841c834b5d56', '9', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ بْنُ أَبِي إِيَاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ ‏ ‏وَإِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏وَقَالَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ هُوَ ابْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b6a6bc13-a2aa-5f46-ade5-3c60a237066d', '5cb5e738-220a-4267-901a-841c834b5d56', '10', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَحْيَى بْنِ سَعِيدٍ الْقُرَشِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بُرْدَةَ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ أَيُّ الْإِسْلَامِ أَفْضَلُ قَالَ ‏ ‏مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('565240a2-6639-5235-9526-e9e650ede796', '5cb5e738-220a-4267-901a-841c834b5d56', '11', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْإِسْلَامِ خَيْرٌ قَالَ ‏ ‏تُطْعِمُ الطَّعَامَ وَتَقْرَأُ السَّلَامَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b3c21398-4529-5b3f-9167-a9f62ed74f61', '5cb5e738-220a-4267-901a-841c834b5d56', '12', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْ ‏ ‏حُسَيْنٍ الْمُعَلِّمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُؤْمِنُ ‏ ‏أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b1a1149a-0121-5758-b6be-d6e588a1db9e', '5cb5e738-220a-4267-901a-841c834b5d56', '13', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَوَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَا يُؤْمِنُ ‏ ‏أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('18fe8e52-a9dd-5eb6-a224-ad73dfe5a2c6', '5cb5e738-220a-4267-901a-841c834b5d56', '14', '‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ ‏ ‏أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7ee6e4ec-f732-574b-9c8a-95f97b865af5', '5cb5e738-220a-4267-901a-841c834b5d56', '15', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلَاوَةَ الْإِيمَانِ أَنْ يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَأَنْ يُحِبَّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ وَأَنْ يَكْرَهَ أَنْ يَعُودَ فِي الْكُفْرِ كَمَا يَكْرَهُ أَنْ ‏ ‏يُقْذَفَ ‏ ‏فِي النَّارِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2f83bea1-36f9-5683-92ef-66504f0e4c44', '5cb5e738-220a-4267-901a-841c834b5d56', '16', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏آيَةُ ‏ ‏الْإِيمَانِ حُبُّ ‏ ‏الْأَنْصَارِ ‏ ‏وَآيَةُ ‏ ‏النِّفَاقِ بُغْضُ ‏ ‏الْأَنْصَارِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8168f1ac-a20f-5ab9-9922-949dd92ac8e6', '5cb5e738-220a-4267-901a-841c834b5d56', '17', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو إِدْرِيسَ عَائِذُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عُبَادَةَ بْنَ الصَّامِتِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَكَانَ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَهُوَ أَحَدُ ‏ ‏النُّقَبَاءِ ‏ ‏لَيْلَةَ ‏ ‏الْعَقَبَةِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَحَوْلَهُ ‏ ‏عِصَابَةٌ ‏ ‏مِنْ أَصْحَابِهِ ‏ ‏بَايِعُونِي ‏ ‏عَلَى أَنْ لَا تُشْرِكُوا بِاللَّهِ شَيْئًا وَلَا تَسْرِقُوا وَلَا تَزْنُوا وَلَا تَقْتُلُوا أَوْلَادَكُمْ وَلَا تَأْتُوا ‏ ‏بِبُهْتَانٍ ‏ ‏تَفْتَرُونَهُ ‏ ‏بَيْنَ أَيْدِيكُمْ وَأَرْجُلِكُمْ وَلَا تَعْصُوا فِي مَعْرُوفٍ فَمَنْ وَفَى مِنْكُمْ فَأَجْرُهُ عَلَى اللَّهِ وَمَنْ ‏ ‏أَصَابَ ‏ ‏مِنْ ذَلِكَ شَيْئًا فَعُوقِبَ فِي الدُّنْيَا فَهُوَ كَفَّارَةٌ لَهُ وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا ثُمَّ سَتَرَهُ اللَّهُ فَهُوَ إِلَى اللَّهِ إِنْ شَاءَ عَفَا عَنْهُ وَإِنْ شَاءَ عَاقَبَهُ فَبَايَعْنَاهُ عَلَى ذَلِك ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dcace0c8-f8cb-5c7c-879a-77ae1944ccaa', '5cb5e738-220a-4267-901a-841c834b5d56', '18', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ أَنْ يَكُونَ خَيْرَ مَالِ الْمُسْلِمِ غَنَمٌ يَتْبَعُ بِهَا ‏ ‏شَعَفَ ‏ ‏الْجِبَالِ ‏ ‏وَمَوَاقِعَ الْقَطْرِ ‏ ‏يَفِرُّ بِدِينِهِ مِنْ الْفِتَنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('46d54107-91a5-5b32-baab-ad20067b5c60', '5cb5e738-220a-4267-901a-841c834b5d56', '19', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَامٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَمَرَهُمْ أَمَرَهُمْ مِنْ الْأَعْمَالِ بِمَا يُطِيقُونَ قَالُوا إِنَّا لَسْنَا ‏ ‏كَهَيْئَتِكَ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ قَدْ غَفَرَ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ فَيَغْضَبُ حَتَّى يُعْرَفَ الْغَضَبُ فِي وَجْهِهِ ثُمَّ يَقُولُ ‏ ‏إِنَّ ‏ ‏أَتْقَاكُمْ ‏ ‏وَأَعْلَمَكُمْ بِاللَّهِ أَنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da8856ec-90c8-5584-b22a-6f24967391bb', '5cb5e738-220a-4267-901a-841c834b5d56', '20', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلَاوَةَ الْإِيمَانِ مَنْ كَانَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَمَنْ أَحَبَّ عَبْدًا لَا يُحِبُّهُ إِلَّا لِلَّهِ عَزَّ وَجَلَّ وَمَنْ يَكْرَهُ أَنْ يَعُودَ فِي الْكُفْرِ بَعْدَ إِذْ أَنْقَذَهُ اللَّهُ مِنْهُ كَمَا يَكْرَهُ أَنْ يُلْقَى فِي النَّارِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('78af6507-0f8e-5c43-8286-1c3a22186029', '5cb5e738-220a-4267-901a-841c834b5d56', '21', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَدْخُلُ أَهْلُ الْجَنَّةِ الْجَنَّةَ وَأَهْلُ النَّارِ النَّارَ ثُمَّ يَقُولُ اللَّهُ تَعَالَى ‏ ‏أَخْرِجُوا مِنْ النَّارِ مَنْ كَانَ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ إِيمَانٍ فَيُخْرَجُونَ مِنْهَا قَدْ اسْوَدُّوا فَيُلْقَوْنَ فِي نَهَرِ الْحَيَا ‏ ‏أَوْ الْحَيَاةِ شَكَّ ‏ ‏مَالِكٌ ‏ ‏فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي جَانِبِ السَّيْلِ أَلَمْ تَرَ أَنَّهَا تَخْرُجُ صَفْرَاءَ مُلْتَوِيَةً ‏ ‏قَالَ ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرٌو ‏ ‏الْحَيَاةِ وَقَالَ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ خَيْرٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3cd252a1-089a-5610-89db-9337c02172b4', '5cb5e738-220a-4267-901a-841c834b5d56', '22', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَا أَنَا نَائِمٌ رَأَيْتُ النَّاسَ ‏ ‏يُعْرَضُونَ ‏ ‏عَلَيَّ وَعَلَيْهِمْ قُمُصٌ مِنْهَا مَا يَبْلُغُ الثُّدِيَّ وَمِنْهَا مَا دُونَ ذَلِكَ وَعُرِضَ عَلَيَّ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَعَلَيْهِ قَمِيصٌ يَجُرُّهُ قَالُوا فَمَا ‏ ‏أَوَّلْتَ ‏ ‏ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ الدِّينَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8b8ef373-181d-589b-af3f-a0a2fcbe9eed', '5cb5e738-220a-4267-901a-841c834b5d56', '23', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى رَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَهُوَ يَعِظُ أَخَاهُ فِي الْحَيَاءِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُ فَإِنَّ الْحَيَاءَ مِنْ الْإِيمَانِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2584beb2-18d4-5c82-a045-2a95bef8dcdf', '5cb5e738-220a-4267-901a-841c834b5d56', '24', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ الْمُسْنَدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو رَوْحٍ الْحَرَمِيُّ بْنُ عُمَارَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى ‏ ‏يَشْهَدُوا ‏ ‏أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ فَإِذَا فَعَلُوا ذَلِكَ ‏ ‏عَصَمُوا ‏ ‏مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّ الْإِسْلَامِ وَحِسَابُهُمْ عَلَى اللَّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e2d09c3a-6473-53e3-9fa2-289751037313', '5cb5e738-220a-4267-901a-841c834b5d56', '25', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏وَمُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ أَيُّ الْعَمَلِ أَفْضَلُ فَقَالَ ‏ ‏إِيمَانٌ بِاللَّهِ وَرَسُولِهِ قِيلَ ثُمَّ مَاذَا قَالَ الْجِهَادُ فِي سَبِيلِ اللَّهِ قِيلَ ثُمَّ مَاذَا قَالَ حَجٌّ ‏ ‏مَبْرُورٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4ebd7ec8-da98-5828-b8ff-dafa5c49b18c', '5cb5e738-220a-4267-901a-841c834b5d56', '26', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَامِرُ بْنُ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطَى ‏ ‏رَهْطًا ‏ ‏وَسَعْدٌ ‏ ‏جَالِسٌ فَتَرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا هُوَ ‏ ‏أَعْجَبُهُمْ ‏ ‏إِلَيَّ فَقُلْتُ يَا رَسُولَ اللَّهِ مَا لَكَ عَنْ فُلَانٍ فَوَاللَّهِ إِنِّي لَأَرَاهُ مُؤْمِنًا فَقَالَ أَوْ مُسْلِمًا فَسَكَتُّ قَلِيلًا ثُمَّ ‏ ‏غَلَبَنِي ‏ ‏مَا أَعْلَمُ مِنْهُ فَعُدْتُ لِمَقَالَتِي فَقُلْتُ مَا لَكَ عَنْ فُلَانٍ فَوَاللَّهِ إِنِّي لَأَرَاهُ مُؤْمِنًا فَقَالَ أَوْ مُسْلِمًا ثُمَّ ‏ ‏غَلَبَنِي ‏ ‏مَا أَعْلَمُ مِنْهُ فَعُدْتُ لِمَقَالَتِي وَعَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ يَا ‏ ‏سَعْدُ ‏ ‏إِنِّي ‏ ‏لَأُعْطِي الرَّجُلَ وَغَيْرُهُ أَحَبُّ إِلَيَّ مِنْهُ خَشْيَةَ أَنْ ‏ ‏يَكُبَّهُ ‏ ‏اللَّهُ فِي النَّارِ ‏ ‏وَرَوَاهُ ‏ ‏يُونُسُ ‏ ‏وَصَالِحٌ ‏ ‏وَمَعْمَرٌ ‏ ‏وَابْنُ أَخِي الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e1b56284-3933-539e-8f02-eb1de59bb997', '5cb5e738-220a-4267-901a-841c834b5d56', '27', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْإِسْلَامِ خَيْرٌ قَالَ ‏ ‏تُطْعِمُ الطَّعَامَ وَتَقْرَأُ السَّلَامَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a2225b1d-4c6a-578d-ba3b-23ae47316e6f', '5cb5e738-220a-4267-901a-841c834b5d56', '28', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُرِيتُ النَّارَ فَإِذَا أَكْثَرُ أَهْلِهَا النِّسَاءُ يَكْفُرْنَ قِيلَ أَيَكْفُرْنَ بِاللَّهِ قَالَ ‏ ‏يَكْفُرْنَ ‏ ‏الْعَشِيرَ ‏ ‏وَيَكْفُرْنَ ‏ ‏الْإِحْسَانَ لَوْ أَحْسَنْتَ إِلَى إِحْدَاهُنَّ الدَّهْرَ ثُمَّ رَأَتْ مِنْكَ شَيْئًا قَالَتْ مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('52a4861b-3265-528e-b758-2c561327823e', '5cb5e738-220a-4267-901a-841c834b5d56', '29', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاصِلٍ الْأَحْدَبِ ‏ ‏عَنْ ‏ ‏الْمَعْرُورِ بْنِ سُوَيْدٍ ‏ ‏قَالَ لَقِيتُ ‏ ‏أَبَا ذَرٍّ ‏ ‏بِالرَّبَذَةِ ‏ ‏وَعَلَيْهِ ‏ ‏حُلَّةٌ ‏ ‏وَعَلَى غُلَامِهِ ‏ ‏حُلَّةٌ ‏ ‏فَسَأَلْتُهُ عَنْ ذَلِكَ فَقَالَ إِنِّي سَابَبْتُ ‏ ‏رَجُلًا ‏ ‏فَعَيَّرْتُهُ بِأُمِّهِ فَقَالَ لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا ذَرٍّ ‏ ‏أَعَيَّرْتَهُ بِأُمِّهِ إِنَّكَ امْرُؤٌ فِيكَ جَاهِلِيَّةٌ إِخْوَانُكُمْ ‏ ‏خَوَلُكُمْ ‏ ‏جَعَلَهُمْ اللَّهُ تَحْتَ أَيْدِيكُمْ فَمَنْ كَانَ أَخُوهُ تَحْتَ يَدِهِ فَلْيُطْعِمْهُ مِمَّا يَأْكُلُ وَلْيُلْبِسْهُ مِمَّا يَلْبَسُ وَلَا تُكَلِّفُوهُمْ مَا ‏ ‏يَغْلِبُهُمْ ‏ ‏فَإِنْ كَلَّفْتُمُوهُمْ فَأَعِينُوهُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('120e9365-fc94-5924-a8ec-30d1f6adfa35', '5cb5e738-220a-4267-901a-841c834b5d56', '30', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏وَيُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏ذَهَبْتُ لِأَنْصُرَ هَذَا ‏ ‏الرَّجُلَ ‏ ‏فَلَقِيَنِي ‏ ‏أَبُو بَكْرَةَ ‏ ‏فَقَالَ أَيْنَ تُرِيدُ قُلْتُ أَنْصُرُ هَذَا ‏ ‏الرَّجُلَ ‏ ‏قَالَ ارْجِعْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا الْتَقَى الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ فَقُلْتُ يَا رَسُولَ اللَّهِ هَذَا الْقَاتِلُ فَمَا بَالُ الْمَقْتُولِ قَالَ إِنَّهُ كَانَ حَرِيصًا عَلَى قَتْلِ صَاحِبِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1026d839-c831-5d3f-8e0f-9a1d3ae69000', '5cb5e738-220a-4267-901a-841c834b5d56', '31', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏ح ‏ ‏قَالَ ‏ ‏و حَدَّثَنِي ‏ ‏بِشْرُ بْنُ خَالِدٍ أَبُو مُحَمَّدٍ الْعَسْكَرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏الَّذِينَ آمَنُوا وَلَمْ ‏ ‏يَلْبِسُوا ‏ ‏إِيمَانَهُمْ ‏ ‏بِظُلْمٍ ‏ } ‏قَالَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّنَا لَمْ يَظْلِمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ ‏}', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ad70e472-bcfc-510a-8c8c-4ffefb834b7d', '5cb5e738-220a-4267-901a-841c834b5d56', '32', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ أَبُو الرَّبِيعِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏نَافِعُ بْنُ مَالِكِ بْنِ أَبِي عَامِرٍ أَبُو سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏آيَةُ ‏ ‏الْمُنَافِقِ ثَلَاثٌ إِذَا حَدَّثَ كَذَبَ وَإِذَا وَعَدَ ‏ ‏أَخْلَفَ ‏ ‏وَإِذَا اؤْتُمِنَ خَانَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('de771972-0351-5f00-9ad0-7933a8889e2a', '5cb5e738-220a-4267-901a-841c834b5d56', '33', '‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ بْنُ عُقْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْبَعٌ مَنْ كُنَّ فِيهِ كَانَ مُنَافِقًا ‏ ‏خَالِصًا ‏ ‏وَمَنْ كَانَتْ فِيهِ خَصْلَةٌ مِنْهُنَّ كَانَتْ فِيهِ خَصْلَةٌ مِنْ النِّفَاقِ حَتَّى يَدَعَهَا إِذَا اؤْتُمِنَ خَانَ وَإِذَا حَدَّثَ كَذَبَ وَإِذَا ‏ ‏عَاهَدَ ‏ ‏غَدَرَ وَإِذَا خَاصَمَ ‏ ‏فَجَرَ ‏ ‏تَابَعَهُ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5df9dc8a-6166-5f1e-b91d-8f435226cad9', '5cb5e738-220a-4267-901a-841c834b5d56', '34', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَقُمْ لَيْلَةَ الْقَدْرِ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('06c636e7-0159-5fde-bc3a-d83f392826f2', '5cb5e738-220a-4267-901a-841c834b5d56', '35', '‏ ‏حَدَّثَنَا ‏ ‏حَرَمِيُّ بْنُ حَفْصٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَارَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو زُرْعَةَ بْنُ عَمْرِو بْنِ جَرِيرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏انْتَدَبَ ‏ ‏اللَّهُ لِمَنْ خَرَجَ فِي سَبِيلِهِ لَا يُخْرِجُهُ إِلَّا إِيمَانٌ بِي وَتَصْدِيقٌ بِرُسُلِي أَنْ أُرْجِعَهُ بِمَا نَالَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ أَوْ أُدْخِلَهُ الْجَنَّةَ وَلَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي ‏ ‏مَا قَعَدْتُ ‏ ‏خَلْفَ ‏ ‏سَرِيَّةٍ ‏ ‏وَلَوَدِدْتُ أَنِّي أُقْتَلُ فِي سَبِيلِ اللَّهِ ثُمَّ أُحْيَا ثُمَّ أُقْتَلُ ثُمَّ أُحْيَا ثُمَّ أُقْتَلُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ce06aa9e-a65d-50df-893c-3e0f93a29989', '5cb5e738-220a-4267-901a-841c834b5d56', '36', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَامَ رَمَضَانَ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dff8b668-6686-50fb-8f57-0c517cdeea9d', '5cb5e738-220a-4267-901a-841c834b5d56', '37', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَامٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَامَ رَمَضَانَ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('feb116ea-b487-564e-a0c6-3646fafa4ec6', '5cb5e738-220a-4267-901a-841c834b5d56', '38', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ السَّلَامِ بْنُ مُطَهَّرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏مَعْنِ بْنِ مُحَمَّدٍ الْغِفَارِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الدِّينَ يُسْرٌ وَلَنْ ‏ ‏يُشَادَّ ‏ ‏الدِّينَ أَحَدٌ إِلَّا ‏ ‏غَلَبَهُ ‏ ‏فَسَدِّدُوا ‏ ‏وَقَارِبُوا ‏ ‏وَأَبْشِرُوا وَاسْتَعِينُوا ‏ ‏بِالْغَدْوَةِ ‏ ‏وَالرَّوْحَةِ ‏ ‏وَشَيْءٍ مِنْ ‏ ‏الدُّلْجَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7c119093-b2e9-5c16-a61f-23cb8a189cb4', '5cb5e738-220a-4267-901a-841c834b5d56', '39', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ أَوَّلَ مَا قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏نَزَلَ عَلَى أَجْدَادِهِ ‏ ‏أَوْ قَالَ أَخْوَالِهِ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَأَنَّهُ ‏ ‏صَلَّى ‏ ‏قِبَلَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏سِتَّةَ عَشَرَ شَهْرًا أَوْ سَبْعَةَ عَشَرَ شَهْرًا وَكَانَ يُعْجِبُهُ أَنْ تَكُونَ قِبْلَتُهُ ‏ ‏قِبَلَ ‏ ‏الْبَيْتِ ‏ ‏وَأَنَّهُ صَلَّى أَوَّلَ صَلَاةٍ صَلَّاهَا صَلَاةَ الْعَصْرِ وَصَلَّى مَعَهُ قَوْمٌ فَخَرَجَ ‏ ‏رَجُلٌ ‏ ‏مِمَّنْ صَلَّى مَعَهُ فَمَرَّ عَلَى ‏ ‏أَهْلِ مَسْجِدٍ ‏ ‏وَهُمْ رَاكِعُونَ فَقَالَ أَشْهَدُ بِاللَّهِ لَقَدْ صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِبَلَ ‏ ‏مَكَّةَ ‏ ‏فَدَارُوا كَمَا هُمْ ‏ ‏قِبَلَ ‏ ‏الْبَيْتِ ‏ ‏وَكَانَتْ ‏ ‏الْيَهُودُ ‏ ‏قَدْ أَعْجَبَهُمْ إِذْ كَانَ ‏ ‏يُصَلِّي ‏ ‏قِبَلَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏وَأَهْلُ الْكِتَابِ ‏ ‏فَلَمَّا ‏ ‏وَلَّى ‏ ‏وَجْهَهُ ‏ ‏قِبَلَ ‏ ‏الْبَيْتِ ‏ ‏أَنْكَرُوا ذَلِكَ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ ‏ ‏فِي حَدِيثِهِ هَذَا أَنَّهُ مَاتَ عَلَى الْقِبْلَةِ قَبْلَ أَنْ تُحَوَّلَ رِجَالٌ وَقُتِلُوا فَلَمْ نَدْرِ مَا نَقُولُ فِيهِمْ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ ‏}', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7af568f6-9739-5d18-bc0f-939cccfc5e3b', '5cb5e738-220a-4267-901a-841c834b5d56', '40', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَحْسَنَ أَحَدُكُمْ إِسْلَامَهُ فَكُلُّ حَسَنَةٍ يَعْمَلُهَا تُكْتَبُ لَهُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِ مِائَةِ ضِعْفٍ وَكُلُّ سَيِّئَةٍ يَعْمَلُهَا تُكْتَبُ لَهُ بِمِثْلِهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4df92573-3ece-52b7-8d38-7fba01986f75', '5cb5e738-220a-4267-901a-841c834b5d56', '41', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَعِنْدَهَا ‏ ‏امْرَأَةٌ ‏ ‏قَالَ مَنْ هَذِهِ قَالَتْ فُلَانَةُ تَذْكُرُ مِنْ صَلَاتِهَا قَالَ ‏ ‏مَهْ ‏ ‏عَلَيْكُمْ بِمَا تُطِيقُونَ فَوَاللَّهِ لَا يَمَلُّ اللَّهُ حَتَّى تَمَلُّوا وَكَانَ أَحَبَّ الدِّينِ إِلَيْهِ مَادَامَ عَلَيْهِ صَاحِبُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa73f58a-2f85-53be-9d88-6055347fbd76', '5cb5e738-220a-4267-901a-841c834b5d56', '42', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَفِي قَلْبِهِ وَزْنُ شَعِيرَةٍ مِنْ خَيْرٍ وَيَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَفِي قَلْبِهِ وَزْنُ ‏ ‏بُرَّةٍ ‏ ‏مِنْ خَيْرٍ وَيَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَفِي قَلْبِهِ وَزْنُ ذَرَّةٍ مِنْ خَيْرٍ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِيمَانٍ مَكَانَ مِنْ خَيْرٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('38006f7e-65e8-5771-8de2-2406e12f21a3', '5cb5e738-220a-4267-901a-841c834b5d56', '43', '‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ الصَّبَّاحِ ‏ ‏سَمِعَ ‏ ‏جَعْفَرَ بْنَ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعُمَيْسِ ‏ ‏أَخْبَرَنَا ‏ ‏قَيْسُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏الْيَهُودِ ‏ ‏قَالَ لَهُ يَا أَمِيرَ الْمُؤْمِنِينَ آيَةٌ فِي كِتَابِكُمْ تَقْرَءُونَهَا لَوْ عَلَيْنَا ‏ ‏مَعْشَرَ ‏ ‏الْيَهُودِ ‏ ‏نَزَلَتْ لَاتَّخَذْنَا ذَلِكَ الْيَوْمَ عِيدًا قَالَ أَيُّ آيَةٍ قَالَ ‏ { ‏الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمْ الْإِسْلَامَ دِينًا ‏} ‏قَالَ ‏ ‏عُمَرُ ‏ ‏قَدْ ‏ ‏عَرَفْنَا ذَلِكَ الْيَوْمَ وَالْمَكَانَ الَّذِي نَزَلَتْ فِيهِ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ قَائِمٌ ‏ ‏بِعَرَفَةَ ‏ ‏يَوْمَ جُمُعَةٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('70d4a5a9-a0df-5804-93b1-45fc2bfede91', '5cb5e738-220a-4267-901a-841c834b5d56', '44', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي سُهَيْلِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏طَلْحَةَ بْنَ عُبَيْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏أَهْلِ ‏ ‏نَجْدٍ ‏ ‏ثَائِرَ ‏ ‏الرَّأْسِ يُسْمَعُ ‏ ‏دَوِيُّ ‏ ‏صَوْتِهِ وَلَا يُفْقَهُ مَا يَقُولُ حَتَّى ‏ ‏دَنَا ‏ ‏فَإِذَا هُوَ يَسْأَلُ عَنْ الْإِسْلَامِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ فَقَالَ هَلْ عَلَيَّ غَيْرُهَا قَالَ لَا إِلَّا أَنْ تَطَوَّعَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصِيَامُ رَمَضَانَ قَالَ هَلْ عَلَيَّ غَيْرُهُ قَالَ لَا إِلَّا أَنْ تَطَوَّعَ قَالَ وَذَكَرَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الزَّكَاةَ قَالَ هَلْ عَلَيَّ غَيْرُهَا قَالَ لَا إِلَّا أَنْ تَطَوَّعَ قَالَ فَأَدْبَرَ ‏ ‏الرَّجُلُ ‏ ‏وَهُوَ يَقُولُ وَاللَّهِ لَا أَزِيدُ عَلَى هَذَا وَلَا أَنْقُصُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْلَحَ إِنْ صَدَقَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b398c3e4-7aa1-5099-ae83-dd3ccec0ab35', '5cb5e738-220a-4267-901a-841c834b5d56', '45', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ عَلِيٍّ الْمَنْجُوفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَمُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اتَّبَعَ جَنَازَةَ مُسْلِمٍ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏وَكَانَ مَعَهُ حَتَّى يُصَلَّى عَلَيْهَا وَيَفْرُغَ مِنْ دَفْنِهَا فَإِنَّه يَرْجِعُ مِنْ الْأَجْرِ بِقِيرَاطَيْنِ كُلُّ قِيرَاطٍ مِثْلُ ‏ ‏أُحُدٍ ‏ ‏وَمَنْ صَلَّى عَلَيْهَا ثُمَّ رَجَعَ قَبْلَ أَنْ تُدْفَنَ فَإِنَّهُ يَرْجِعُ بِقِيرَاطٍ ‏ ‏تَابَعَهُ ‏ ‏عُثْمَانُ الْمُؤَذِّنُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5c6f408f-7231-5688-9ccf-0ea2c51e617d', '5cb5e738-220a-4267-901a-841c834b5d56', '46', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَرْعَرَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏عَنْ ‏ ‏الْمُرْجِئَةِ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سِبَابُ الْمُسْلِمِ فُسُوقٌ وَقِتَالُهُ ‏ ‏كُفْرٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c81a8ad4-3c11-5888-be7f-968a336d5820', '5cb5e738-220a-4267-901a-841c834b5d56', '47', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَادَةُ بْنُ الصَّامِتِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يُخْبِرُ بِلَيْلَةِ الْقَدْرِ ‏ ‏فَتَلَاحَى ‏ ‏رَجُلَانِ ‏ ‏مِنْ الْمُسْلِمِينَ فَقَالَ ‏ ‏إِنِّي خَرَجْتُ لِأُخْبِرَكُمْ بِلَيْلَةِ الْقَدْرِ وَإِنَّهُ ‏ ‏تَلَاحَى ‏ ‏فُلَانٌ وَفُلَانٌ ‏ ‏فَرُفِعَتْ ‏ ‏وَعَسَى أَنْ يَكُونَ خَيْرًا لَكُمْ ‏ ‏الْتَمِسُوهَا ‏ ‏فِي السَّبْعِ وَالتِّسْعِ وَالْخَمْسِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('55292797-527c-5ac3-ab21-dfa505d3af73', '5cb5e738-220a-4267-901a-841c834b5d56', '48', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو حَيَّانَ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَارِزًا يَوْمًا لِلنَّاسِ فَأَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏فَقَالَ مَا الْإِيمَانُ قَالَ ‏ ‏الْإِيمَانُ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَبِلِقَائِهِ وَرُسُلِهِ وَتُؤْمِنَ بِالْبَعْثِ قَالَ مَا الْإِسْلَامُ قَالَ الْإِسْلَامُ أَنْ تَعْبُدَ اللَّهَ وَلَا تُشْرِكَ بِهِ شَيْئًا وَتُقِيمَ الصَّلَاةَ وَتُؤَدِّيَ الزَّكَاةَ الْمَفْرُوضَةَ وَتَصُومَ رَمَضَانَ قَالَ مَا الْإِحْسَانُ قَالَ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ قَالَ مَتَى السَّاعَةُ قَالَ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنْ السَّائِلِ وَسَأُخْبِرُكَ عَنْ ‏ ‏أَشْرَاطِهَا ‏ ‏إِذَا وَلَدَتْ الْأَمَةُ ‏ ‏رَبَّهَا ‏ ‏وَإِذَا ‏ ‏تَطَاوَلَ ‏ ‏رُعَاةُ الْإِبِلِ ‏ ‏الْبُهْمُ ‏ ‏فِي الْبُنْيَانِ فِي خَمْسٍ لَا يَعْلَمُهُنَّ إِلَّا اللَّهُ ثُمَّ تَلَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ ‏} ‏الْآيَةَ ثُمَّ ‏ ‏أَدْبَرَ ‏ ‏فَقَالَ رُدُّوهُ فَلَمْ يَرَوْا شَيْئًا فَقَالَ هَذَا ‏ ‏جِبْرِيلُ ‏ ‏جَاءَ يُعَلِّمُ النَّاسَ دِينَهُمْ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏جَعَلَ ذَلِك كُلَّهُ مِنْ الْإِيمَانِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cfd5c169-fb26-58ee-a75c-b502868183cd', '5cb5e738-220a-4267-901a-841c834b5d56', '49', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ حَمْزَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ قَالَ أَخْبَرَنِي ‏ ‏أَبُو سُفْيَانَ بْنُ حَرْبٍ ‏ ‏أَنَّ ‏ ‏هِرَقْلَ ‏ ‏قَالَ لَهُ سَأَلْتُكَ هَلْ يَزِيدُونَ أَمْ يَنْقُصُونَ فَزَعَمْتَ أَنَّهُمْ يَزِيدُونَ وَكَذَلِكَ الْإِيمَانُ حَتَّى يَتِمَّ وَسَأَلْتُكَ هَلْ يَرْتَدُّ أَحَدٌ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ فَزَعَمْتَ أَنْ لَا وَكَذَلِكَ الْإِيمَانُ حِينَ تُخَالِطُ بَشَاشَتُهُ الْقُلُوبَ لَا يَسْخَطُهُ أَحَدٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a3ea8c2c-5afc-5c03-9310-20e7572bdda8', '5cb5e738-220a-4267-901a-841c834b5d56', '50', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّاءُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْحَلَالُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ وَبَيْنَهُمَا مُشَبَّهَاتٌ لَا يَعْلَمُهَا كَثِيرٌ مِنْ النَّاسِ فَمَنْ اتَّقَى الْمُشَبَّهَاتِ ‏ ‏اسْتَبْرَأَ ‏ ‏لِدِينِهِ وَعِرْضِهِ وَمَنْ وَقَعَ فِي ‏ ‏الشُّبُهَاتِ ‏ ‏كَرَاعٍ يَرْعَى حَوْلَ ‏ ‏الْحِمَى ‏ ‏يُوشِكُ أَنْ ‏ ‏يُوَاقِعَهُ ‏ ‏أَلَا وَإِنَّ لِكُلِّ مَلِكٍ ‏ ‏حِمًى ‏ ‏أَلَا إِنَّ ‏ ‏حِمَى ‏ ‏اللَّهِ فِي أَرْضِهِ ‏ ‏مَحَارِمُهُ ‏ ‏أَلَا وَإِنَّ فِي الْجَسَدِ ‏ ‏مُضْغَةً ‏ ‏إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ أَلَا وَهِيَ الْقَلْبُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('74eb5d65-9c2f-5fa3-a5d7-86e50af2af7e', '5cb5e738-220a-4267-901a-841c834b5d56', '51', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْجَعْدِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَقْعُدُ مَعَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يُجْلِسُنِي عَلَى سَرِيرِهِ فَقَالَ أَقِمْ عِنْدِي حَتَّى أَجْعَلَ لَكَ ‏ ‏سَهْمًا ‏ ‏مِنْ مَالِي فَأَقَمْتُ مَعَهُ شَهْرَيْنِ ثُمَّ قَالَ إِنَّ ‏ ‏وَفْدَ عَبْدِ الْقَيْسِ ‏ ‏لَمَّا أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ الْقَوْمُ ‏ ‏أَوْ مَنْ الْوَفْدُ ‏ ‏قَالُوا ‏ ‏رَبِيعَةُ ‏ ‏قَالَ مَرْحَبًا بِالْقَوْمِ ‏ ‏أَوْ بِالْوَفْدِ ‏ ‏غَيْرَ خَزَايَا وَلَا نَدَامَى فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا لَا نَسْتَطِيعُ أَنْ نَأْتِيكَ إِلَّا فِي الشَّهْرِ الْحَرَامِ وَبَيْنَنَا وَبَيْنَكَ هَذَا الْحَيُّ مِنْ كُفَّارِ ‏ ‏مُضَرَ ‏ ‏فَمُرْنَا بِأَمْرٍ ‏ ‏فَصْلٍ ‏ ‏نُخْبِرْ بِهِ مَنْ وَرَاءَنَا وَنَدْخُلْ بِهِ الْجَنَّةَ وَسَأَلُوهُ عَنْ الْأَشْرِبَةِ ‏ ‏فَأَمَرَهُمْ بِأَرْبَعٍ وَنَهَاهُمْ عَنْ أَرْبَعٍ أَمَرَهُمْ بِالْإِيمَانِ بِاللَّهِ وَحْدَهُ قَالَ أَتَدْرُونَ مَا الْإِيمَانُ بِاللَّهِ وَحْدَهُ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ وَإِقَامُ الصَّلَاةِ وَإِيتَاءُ الزَّكَاةِ وَصِيَامُ رَمَضَانَ وَأَنْ تُعْطُوا مِنْ الْمَغْنَمِ الْخُمُسَ وَنَهَاهُمْ عَنْ أَرْبَعٍ عَنْ ‏ ‏الْحَنْتَمِ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏الْمُقَيَّرِ ‏ ‏وَقَالَ احْفَظُوهُنَّ وَأَخْبِرُوا بِهِنَّ مَنْ وَرَاءَكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bbae9f71-74c9-5a78-9a53-88fb5410190d', '5cb5e738-220a-4267-901a-841c834b5d56', '52', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ وَقَّاصٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَعْمَالُ بِالنِّيَّةِ وَلِكُلِّ امْرِئٍ مَا نَوَى فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ وَمَنْ كَانَتْ هِجْرَتُهُ لدُنْيَا يُصِيبُهَا أَوْ امْرَأَةٍ يَتَزَوَّجُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ac9f1356-8f8b-5ac4-8900-101ba1de32e4', '5cb5e738-220a-4267-901a-841c834b5d56', '53', '‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَنْفَقَ الرَّجُلُ عَلَى أَهْلِهِ ‏ ‏يَحْتَسِبُهَا ‏ ‏فَهُوَ لَهُ صَدَقَةٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('611bb84d-28a5-53b7-b0ec-3d35d0450d5d', '5cb5e738-220a-4267-901a-841c834b5d56', '54', '‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَامِرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّكَ لَنْ تُنْفِقَ نَفَقَةً تَبْتَغِي بِهَا وَجْهَ اللَّهِ إِلَّا أُجِرْتَ عَلَيْهَا حَتَّى مَا تَجْعَلُ فِي فَمِ امْرَأَتِكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('00434aa7-37af-5b4b-8022-8608662b7cd5', '5cb5e738-220a-4267-901a-841c834b5d56', '55', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَيْسُ بْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1abc1676-8eda-5ddf-bcba-fdd0d6ffdf6b', '5cb5e738-220a-4267-901a-841c834b5d56', '56', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَرِيرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏يَوْمَ مَاتَ ‏ ‏الْمُغِيرَةُ بْنُ شُعْبَةَ ‏ ‏قَامَ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ وَقَالَ عَلَيْكُمْ بِاتِّقَاءِ اللَّهِ وَحْدَهُ لَا شَرِيكَ لَهُ ‏ ‏وَالْوَقَارِ ‏ ‏وَالسَّكِينَةِ ‏ ‏حَتَّى يَأْتِيَكُمْ أَمِيرٌ فَإِنَّمَا ‏ ‏يَأْتِيكُمْ الْآنَ ثُمَّ قَالَ ‏ ‏اسْتَعْفُوا ‏ ‏لِأَمِيرِكُمْ فَإِنَّهُ كَانَ يُحِبُّ الْعَفْوَ ثُمَّ قَالَ أَمَّا بَعْدُ فَإِنِّي أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ أُبَايِعُكَ عَلَى الْإِسْلَامِ فَشَرَطَ عَلَيَّ ‏ ‏وَالنُّصْحِ لِكُلِّ مُسْلِمٍ فَبَايَعْتُهُ عَلَى هَذَا وَرَبِّ هَذَا الْمَسْجِدِ إِنِّي لَنَاصِحٌ لَكُمْ ثُمَّ اسْتَغْفَرَ وَنَزَلَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5f76c947-05fb-5535-9a50-cfb7b6f1f7be', '5cb5e738-220a-4267-901a-841c834b5d56', '57', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سِنَانٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُلَيْحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هِلَالُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَجْلِسٍ يُحَدِّثُ الْقَوْمَ جَاءَهُ أَعْرَابِيٌّ فَقَالَ مَتَى السَّاعَةُ فَمَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُ فَقَالَ بَعْضُ الْقَوْمِ سَمِعَ مَا قَالَ فَكَرِهَ مَا قَالَ وَقَالَ بَعْضُهُمْ بَلْ لَمْ يَسْمَعْ حَتَّى إِذَا قَضَى حَدِيثَهُ قَالَ أَيْنَ أُرَاهُ السَّائِلُ عَنْ السَّاعَةِ قَالَ هَا أَنَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏فَإِذَا ضُيِّعَتْ الْأَمَانَةُ فَانْتَظِرْ السَّاعَةَ قَالَ كَيْفَ إِضَاعَتُهَا قَالَ إِذَا ‏ ‏وُسِّدَ ‏ ‏الْأَمْرُ إِلَى غَيْرِ أَهْلِهِ فَانْتَظِرْ السَّاعَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('847a7ebc-1d13-53d0-97b2-7725c70b54bd', '5cb5e738-220a-4267-901a-841c834b5d56', '58', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ عَارِمُ بْنُ الْفَضْلِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏تَخَلَّفَ عَنَّا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفْرَةٍ سَافَرْنَاهَا فَأَدْرَكَنَا وَقَدْ ‏ ‏أَرْهَقَتْنَا ‏ ‏الصَّلَاةُ وَنَحْنُ نَتَوَضَّأُ فَجَعَلْنَا نَمْسَحُ عَلَى أَرْجُلِنَا فَنَادَى بِأَعْلَى صَوْتِهِ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('17e37e3b-b6ea-58a5-a8fa-8a9e3042293c', '5cb5e738-220a-4267-901a-841c834b5d56', '59', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ الشَّجَرِ شَجَرَةً لَا يَسْقُطُ وَرَقُهَا وَإِنَّهَا مَثَلُ الْمُسْلِمِ فَحَدِّثُونِي مَا هِيَ فَوَقَعَ النَّاسُ فِي شَجَرِ الْبَوَادِي قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَوَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ فَاسْتَحْيَيْتُ ثُمَّ قَالُوا حَدِّثْنَا مَا هِيَ يَا رَسُولَ اللَّهِ قَالَ هِيَ النَّخْلَةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b0a23009-dd57-5602-a8e9-cc09b4eeacdb', '5cb5e738-220a-4267-901a-841c834b5d56', '60', '‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ الشَّجَرِ شَجَرَةً لَا يَسْقُطُ وَرَقُهَا وَإِنَّهَا مَثَلُ الْمُسْلِمِ حَدِّثُونِي مَا هِيَ قَالَ فَوَقَعَ النَّاسُ فِي شَجَرِ الْبَوَادِي قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَوَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ فَاسْتَحْيَيْتُ ثُمَّ قَالُوا حَدِّثْنَا مَا هِيَ يَا رَسُولَ اللَّهِ قَالَ هِيَ النَّخْلَةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fd044b6d-9b40-5252-b39e-78e20ec43606', '5cb5e738-220a-4267-901a-841c834b5d56', '61', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ هُوَ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي نَمِرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏بَيْنَمَا نَحْنُ جُلُوسٌ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ دَخَلَ رَجُلٌ عَلَى جَمَلٍ فَأَنَاخَهُ فِي الْمَسْجِدِ ثُمَّ عَقَلَهُ ثُمَّ قَالَ لَهُمْ أَيُّكُمْ ‏ ‏مُحَمَّدٌ ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَّكِئٌ بَيْنَ ‏ ‏ظَهْرَانَيْهِمْ ‏ ‏فَقُلْنَا ‏ ‏هَذَا الرَّجُلُ الْأَبْيَضُ الْمُتَّكِئُ فَقَالَ لَهُ الرَّجُلُ يَا ‏ ‏ابْنَ عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ أَجَبْتُكَ فَقَالَ الرَّجُلُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي سَائِلُكَ فَمُشَدِّدٌ عَلَيْكَ فِي الْمَسْأَلَةِ فَلَا ‏ ‏تَجِدْ ‏ ‏عَلَيَّ فِي نَفْسِكَ فَقَالَ سَلْ عَمَّا بَدَا لَكَ فَقَالَ أَسْأَلُكَ بِرَبِّكَ وَرَبِّ مَنْ قَبْلَكَ أَاللَّهُ أَرْسَلَكَ إِلَى النَّاسِ كُلِّهِمْ فَقَالَ اللَّهُمَّ نَعَمْ قَالَ أَنْشُدُكَ بِاللَّهِ أَاللَّهُ أَمَرَكَ أَنْ نُصَلِّيَ الصَّلَوَاتِ الْخَمْسَ فِي الْيَوْمِ وَاللَّيْلَةِ قَالَ اللَّهُمَّ نَعَمْ قَالَ أَنْشُدُكَ بِاللَّهِ أَاللَّهُ أَمَرَكَ أَنْ نَصُومَ هَذَا الشَّهْرَ مِنْ السَّنَةِ قَالَ اللَّهُمَّ نَعَمْ قَالَ أَنْشُدُكَ بِاللَّهِ أَاللَّهُ أَمَرَكَ أَنْ تَأْخُذَ هَذِهِ الصَّدَقَةَ مِنْ أَغْنِيَائِنَا فَتَقْسِمَهَا عَلَى فُقَرَائِنَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ نَعَمْ فَقَالَ الرَّجُلُ آمَنْتُ بِمَا جِئْتَ بِهِ وَأَنَا رَسُولُ مَنْ وَرَائِي مِنْ قَوْمِي وَأَنَا ‏ ‏ضِمَامُ بْنُ ثَعْلَبَةَ ‏ ‏أَخُو ‏ ‏بَنِي سَعْدِ بْنِ بَكْرٍ ‏ ‏وَرَوَاهُ ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏وَعَلِيُّ بْنُ عَبْدِ الْحَمِيدِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ المُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8b045595-ef84-563f-a298-7c28e1d4512e', '5cb5e738-220a-4267-901a-841c834b5d56', '62', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ بِكِتَابِهِ ‏ ‏رَجُلًا ‏ ‏وَأَمَرَهُ أَنْ يَدْفَعَهُ إِلَى ‏ ‏عَظِيمِ ‏ ‏الْبَحْرَيْنِ ‏ ‏فَدَفَعَهُ ‏ ‏عَظِيمُ ‏ ‏الْبَحْرَيْنِ ‏ ‏إِلَى ‏ ‏كِسْرَى ‏ ‏فَلَمَّا قَرَأَهُ مَزَّقَهُ ‏ ‏فَحَسِبْتُ أَنَّ ‏ ‏ابْنَ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏فَدَعَا عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُمَزَّقُوا كُلَّ مُمَزَّقٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f94faf48-65ca-58be-9a10-f5119cd5519c', '5cb5e738-220a-4267-901a-841c834b5d56', '63', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ أَبُو الْحَسَنِ الْمَرْوَزِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَتَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِتَابًا ‏ ‏أَوْ أَرَادَ أَنْ يَكْتُبَ ‏ ‏فَقِيلَ لَهُ إِنَّهُمْ لَا يَقْرَءُونَ كِتَابًا إِلَّا مَخْتُومًا ‏ ‏فَاتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ نَقْشُهُ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ كَأَنِّي أَنْظُرُ إِلَى بَيَاضِهِ فِي يَدِهِ فَقُلْتُ ‏ ‏لِقَتَادَةَ ‏ ‏مَنْ قَالَ نَقْشُهُ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ قَالَ ‏ ‏أَنَسٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('34595cd3-f316-5217-8953-784b75c6a0c6', '5cb5e738-220a-4267-901a-841c834b5d56', '64', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏أَنَّ ‏ ‏أَبَا مُرَّةَ ‏ ‏مَوْلَى ‏ ‏عَقِيلِ بْنِ أَبِي طَالِبٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي وَاقِدٍ اللَّيْثِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا هُوَ جَالِسٌ فِي الْمَسْجِدِ وَالنَّاسُ مَعَهُ إِذْ أَقْبَلَ ثَلَاثَةُ نَفَرٍ فَأَقْبَلَ اثْنَانِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَذَهَبَ وَاحِدٌ قَالَ فَوَقَفَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَّا أَحَدُهُمَا فَرَأَى ‏ ‏فُرْجَةً ‏ ‏فِي الْحَلْقَةِ فَجَلَسَ فِيهَا وَأَمَّا الْآخَرُ فَجَلَسَ خَلْفَهُمْ وَأَمَّا الثَّالِثُ فَأَدْبَرَ ذَاهِبًا فَلَمَّا فَرَغَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ عَنْ النَّفَرِ الثَّلَاثَةِ أَمَّا أَحَدُهُمْ ‏ ‏فَأَوَى ‏ ‏إِلَى اللَّهِ فَآوَاهُ اللَّهُ وَأَمَّا الْآخَرُ فَاسْتَحْيَا فَاسْتَحْيَا اللَّهُ مِنْهُ وَأَمَّا الْآخَرُ فَأَعْرَضَ فَأَعْرَضَ اللَّهُ عَنْهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('13c97ce9-f918-5d22-976c-ff29637ac074', '5cb5e738-220a-4267-901a-841c834b5d56', '65', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بِشْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏ذَكَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَعَدَ عَلَى بَعِيرِهِ وَأَمْسَكَ إِنْسَانٌ ‏ ‏بِخِطَامِهِ ‏ ‏أَوْ بِزِمَامِهِ ‏ ‏قَالَ أَيُّ يَوْمٍ هَذَا فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ سِوَى اسْمِهِ قَالَ أَلَيْسَ يَوْمَ ‏ ‏النَّحْرِ ‏ ‏قُلْنَا بَلَى قَالَ فَأَيُّ شَهْرٍ هَذَا فَسَكَتْنَا حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ فَقَالَ أَلَيْسَ بِذِي الْحِجَّةِ قُلْنَا بَلَى قَالَ ‏ ‏فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ بَيْنَكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا لِيُبَلِّغ الشَّاهِدُ الْغَائِبَ فَإِنَّ الشَّاهِدَ عَسَى أَنْ يُبَلِّغَ مَنْ هُوَ أَوْعَى لَهُ مِنْهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0de61094-4f48-59da-ab7e-a5ac68e7e1ee', '5cb5e738-220a-4267-901a-841c834b5d56', '66', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَوَّلُنَا ‏ ‏بِالْمَوْعِظَةِ فِي الْأَيَّامِ كَرَاهَةَ السَّآمَةِ عَلَيْنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8354a4ae-e72d-54d9-8e09-7798ff688dcc', '5cb5e738-220a-4267-901a-841c834b5d56', '67', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَسِّرُوا وَلَا تُعَسِّرُوا وَبَشِّرُوا وَلَا تُنَفِّرُوا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0ca0df5d-6571-5472-a20f-0e76714f29ec', '5cb5e738-220a-4267-901a-841c834b5d56', '68', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يُذَكِّرُ النَّاسَ فِي كُلِّ خَمِيسٍ فَقَالَ لَهُ رَجُلٌ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏لَوَدِدْتُ أَنَّكَ ذَكَّرْتَنَا كُلَّ يَوْمٍ قَالَ أَمَا إِنَّهُ يَمْنَعُنِي مِنْ ذَلِكَ أَنِّي أَكْرَهُ أَنْ أُمِلَّكُمْ وَإِنِّي ‏ ‏أَتَخَوَّلُكُمْ ‏ ‏بِالْمَوْعِظَةِ كَمَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَوَّلُنَا ‏ ‏بِهَا مَخَافَةَ السَّآمَةِ عَلَيْنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('36298763-3266-5cd9-88cd-7e78d011d290', '5cb5e738-220a-4267-901a-841c834b5d56', '69', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عُفَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ قَالَ ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏خَطِيبًا يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا ‏ ‏يُفَقِّهْهُ فِي الدِّينِ وَإِنَّمَا أَنَا قَاسِمٌ وَاللَّهُ يُعْطِي وَلَنْ تَزَالَ هَذِهِ الْأُمَّةُ قَائِمَةً عَلَى أَمْرِ اللَّهِ لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6bd4b8e6-0903-5906-8800-1f02c5ebab1b', '5cb5e738-220a-4267-901a-841c834b5d56', '70', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ قَالَ لِي ‏ ‏ابْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ صَحِبْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَلَمْ أَسْمَعْهُ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا حَدِيثًا وَاحِدًا قَالَ كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُتِيَ ‏ ‏بِجُمَّارٍ ‏ ‏فَقَالَ ‏ ‏إِنَّ مِنْ الشَّجَرِ شَجَرَةً مَثَلُهَا كَمَثَلِ الْمُسْلِمِ فَأَرَدْتُ أَنْ أَقُولَ هِيَ النَّخْلَةُ فَإِذَا أَنَا أَصْغَرُ الْقَوْمِ فَسَكَتُّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِيَ النَّخْلَةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a3217c71-f3e1-5a5c-a186-665d80791264', '5cb5e738-220a-4267-901a-841c834b5d56', '71', '‏ ‏حَدَّثَنَا ‏ ‏الْحُمَيْدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَلَى غَيْرِ مَا حَدَّثَنَاهُ ‏ ‏الزُّهْرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَيْسَ بْنَ أَبِي حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏حَسَدَ ‏ ‏إِلَّا فِي اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ مَالًا فَسُلِّطَ عَلَى هَلَكَتِهِ فِي الْحَقِّ وَرَجُلٌ آتَاهُ اللَّهُ الْحِكْمَةَ فَهُوَ يَقْضِي بِهَا وَيُعَلِّمُهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('205e3182-e982-5088-8665-c53ea5d85ab1', '5cb5e738-220a-4267-901a-841c834b5d56', '72', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ غُرَيْرٍ الزُّهْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ تَمَارَى هُوَ ‏ ‏وَالْحُرُّ بْنُ قَيْسِ بْنِ حِصْنٍ الْفَزَارِيُّ ‏ ‏فِي صَاحِبِ ‏ ‏مُوسَى ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏هُوَ ‏ ‏خَضِرٌ ‏ ‏فَمَرَّ بِهِمَا ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏فَدَعَاهُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَقَالَ إِنِّي تَمَارَيْتُ أَنَا وَصَاحِبِي هَذَا فِي صَاحِبِ ‏ ‏مُوسَى ‏ ‏الَّذِي سَأَلَ ‏ ‏مُوسَى ‏ ‏السَّبِيلَ إِلَى لُقِيِّهِ هَلْ سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ شَأْنَهُ قَالَ نَعَمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَيْنَمَا ‏ ‏مُوسَى ‏ ‏فِي مَلَإٍ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏جَاءَهُ رَجُلٌ فَقَالَ هَلْ تَعْلَمُ أَحَدًا أَعْلَمَ مِنْكَ قَالَ ‏ ‏مُوسَى ‏ ‏لَا فَأَوْحَى اللَّهُ عَزَّ وَجَلَّ إِلَى ‏ ‏مُوسَى ‏ ‏بَلَى عَبْدُنَا ‏ ‏خَضِرٌ ‏ ‏فَسَأَلَ ‏ ‏مُوسَى ‏ ‏السَّبِيلَ إِلَيْهِ فَجَعَلَ اللَّهُ لَهُ الْحُوتَ آيَةً وَقِيلَ لَهُ إِذَا فَقَدْتَ الْحُوتَ فَارْجِعْ فَإِنَّكَ سَتَلْقَاهُ وَكَانَ يَتَّبِعُ أَثَرَ الْحُوتِ فِي الْبَحْرِ فَقَالَ ‏ ‏لِمُوسَى ‏ ‏فَتَاهُ ‏ { ‏أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ فَإِنِّي نَسِيتُ الْحُوتَ وَمَا ‏ ‏أَنْسَانِيهِ ‏ ‏إِلَّا الشَّيْطَانُ أَنْ أَذْكُرَهُ ‏} { ‏قَالَ ذَلِكَ مَا كُنَّا ‏ ‏نَبْغِي ‏ ‏فَارْتَدَّا عَلَى آثَارِهِمَا قَصَصًا ‏} ‏فَوَجَدَا ‏ ‏خَضِرًا ‏ ‏فَكَانَ مِنْ شَأْنِهِمَا الَّذِي قَصَّ اللَّهُ عَزَّ وَجَلَّ فِي كِتَابِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f768d538-b4a9-5283-acb7-6924d1da1d47', '5cb5e738-220a-4267-901a-841c834b5d56', '73', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏ضَمَّنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏اللَّهُمَّ عَلِّمْهُ الْكِتَابَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('37ea5184-83e2-5628-aae1-161812a3297b', '5cb5e738-220a-4267-901a-841c834b5d56', '74', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي أُوَيْسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَقْبَلْتُ رَاكِبًا عَلَى حِمَارٍ ‏ ‏أَتَانٍ ‏ ‏وَأَنَا يَوْمَئِذٍ قَدْ ‏ ‏نَاهَزْتُ ‏ ‏الِاحْتِلَامَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ‏ ‏بِمِنًى ‏ ‏إِلَى غَيْرِ جِدَارٍ فَمَرَرْتُ بَيْنَ يَدَيْ بَعْضِ الصَّفِّ وَأَرْسَلْتُ ‏ ‏الْأَتَانَ ‏ ‏تَرْتَعُ فَدَخَلْتُ فِي الصَّفِّ فَلَمْ يُنْكَرْ ذَلِكَ عَلَيَّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c72b29a9-4810-5a00-a2e2-9654bb77e7df', '5cb5e738-220a-4267-901a-841c834b5d56', '75', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُسْهِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنِي ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ الرَّبِيعِ ‏ ‏قَالَ ‏ ‏عَقَلْتُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَجَّةً ‏ ‏مَجَّهَا ‏ ‏فِي وَجْهِي وَأَنَا ابْنُ خَمْسِ سِنِينَ مِنْ دَلْوٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('18afcd00-9078-5c25-bbd4-2bc3809a4872', '5cb5e738-220a-4267-901a-841c834b5d56', '76', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْقَاسِمِ خَالِدُ بْنُ خَلِيٍّ ‏ ‏قَاضِي ‏ ‏حِمْصَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ تَمَارَى هُوَ ‏ ‏وَالْحُرُّ بْنُ قَيْسِ بْنِ حِصْنٍ الْفَزَارِيُّ ‏ ‏فِي صَاحِبِ ‏ ‏مُوسَى ‏ ‏فَمَرَّ بِهِمَا ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏فَدَعَاهُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَقَالَ إِنِّي تَمَارَيْتُ أَنَا وَصَاحِبِي هَذَا فِي صَاحِبِ ‏ ‏مُوسَى ‏ ‏الَّذِي سَأَلَ السَّبِيلَ إِلَى لُقِيِّهِ هَلْ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ شَأْنَهُ فَقَالَ ‏ ‏أُبَيٌّ ‏ ‏نَعَمْ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ شَأْنَهُ يَقُولُ ‏ ‏بَيْنَمَا ‏ ‏مُوسَى ‏ ‏فِي مَلَإٍ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏إِذْ جَاءَهُ رَجُلٌ فَقَالَ أَتَعْلَمُ أَحَدًا أَعْلَمَ مِنْكَ قَالَ ‏ ‏مُوسَى ‏ ‏لَا فَأَوْحَى اللَّهُ عَزَّ وَجَلَّ إِلَى ‏ ‏مُوسَى ‏ ‏بَلَى عَبْدُنَا ‏ ‏خَضِرٌ ‏ ‏فَسَأَلَ السَّبِيلَ إِلَى لُقِيِّهِ فَجَعَلَ اللَّهُ لَهُ الْحُوتَ آيَةً وَقِيلَ لَهُ إِذَا فَقَدْتَ الْحُوتَ فَارْجِعْ فَإِنَّكَ سَتَلْقَاهُ فَكَانَ ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ يَتَّبِعُ أَثَرَ الْحُوتِ فِي الْبَحْرِ فَقَالَ فَتَى ‏ ‏مُوسَى ‏ ‏لِمُوسَى ‏ { ‏أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ فَإِنِّي نَسِيتُ الْحُوتَ وَمَا ‏ ‏أَنْسَانِيهِ ‏ ‏إِلَّا الشَّيْطَانُ أَنْ أَذْكُرَهُ ‏} ‏قَالَ ‏ ‏مُوسَى ‏ { ‏ذَلِكَ مَا كُنَّا ‏ ‏نَبْغِي ‏ ‏فَارْتَدَّا عَلَى آثَارِهِمَا قَصَصًا ‏} ‏فَوَجَدَا ‏ ‏خَضِرًا ‏ ‏فَكَانَ مِنْ شَأْنِهِمَا مَا قَصَّ اللَّهُ فِي كِتَابِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a4dedd7b-a6ec-5692-85f2-d99fc29373dd', '5cb5e738-220a-4267-901a-841c834b5d56', '77', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ مَا بَعَثَنِي اللَّهُ بِهِ مِنْ الْهُدَى وَالْعِلْمِ كَمَثَلِ ‏ ‏الْغَيْثِ ‏ ‏الْكَثِيرِ أَصَابَ أَرْضًا فَكَانَ مِنْهَا نَقِيَّةٌ قَبِلَتْ الْمَاءَ فَأَنْبَتَتْ ‏ ‏الْكَلَأَ ‏ ‏وَالْعُشْبَ الْكَثِيرَ وَكَانَتْ مِنْهَا ‏ ‏أَجَادِبُ ‏ ‏أَمْسَكَتْ الْمَاءَ فَنَفَعَ اللَّهُ بِهَا النَّاسَ فَشَرِبُوا وَسَقَوْا وَزَرَعُوا وَأَصَابَتْ مِنْهَا طَائِفَةً أُخْرَى إِنَّمَا هِيَ ‏ ‏قِيعَانٌ ‏ ‏لَا تُمْسِكُ مَاءً وَلَا تُنْبِتُ ‏ ‏كَلَأً ‏ ‏فَذَلِكَ مَثَلُ مَنْ فَقُهَ فِي دِينِ اللَّهِ وَنَفَعَهُ مَا بَعَثَنِي اللَّهُ بِهِ فَعَلِمَ وَعَلَّمَ وَمَثَلُ مَنْ لَمْ يَرْفَعْ بِذَلِكَ رَأْسًا وَلَمْ يَقْبَلْ هُدَى اللَّهِ الَّذِي أُرْسِلْتُ بِهِ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏وَكَانَ مِنْهَا طَائِفَةٌ ‏ ‏قَيَّلَتْ الْمَاءَ قَاعٌ يَعْلُوهُ الْمَاءُ ‏ ‏وَالصَّفْصَفُ الْمُسْتَوِي مِنْ الْأَرْضِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c54f66bf-78b9-519f-977b-a1d6716de59b', '5cb5e738-220a-4267-901a-841c834b5d56', '78', '‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ مَيْسَرَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏مِنْ ‏ ‏أَشْرَاطِ السَّاعَةِ ‏ ‏أَنْ يُرْفَعَ الْعِلْمُ وَيَثْبُتَ الْجَهْلُ وَيُشْرَبَ الْخَمْرُ وَيَظْهَرَ الزِّنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e6c90055-07d4-5628-af89-70d93c477af9', '5cb5e738-220a-4267-901a-841c834b5d56', '79', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ لَأُحَدِّثَنَّكُمْ حَدِيثًا لَا يُحَدِّثُكُمْ أَحَدٌ بَعْدِي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مِنْ ‏ ‏أَشْرَاطِ السَّاعَةِ ‏ ‏أَنْ يَقِلَّ الْعِلْمُ وَيَظْهَرَ الْجَهْلُ وَيَظْهَرَ الزِّنَا وَتَكْثُرَ النِّسَاءُ وَيَقِلَّ الرِّجَالُ حَتَّى يَكُونَ لِخَمْسِينَ امْرَأَةً ‏ ‏الْقَيِّمُ ‏ ‏الْوَاحِدُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f6ddd6d7-85e8-5714-bcc5-51e37a09a3d5', '5cb5e738-220a-4267-901a-841c834b5d56', '80', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عُفَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا نَائِمٌ أُتِيتُ بِقَدَحِ لَبَنٍ فَشَرِبْتُ حَتَّى إِنِّي لَأَرَى الرِّيَّ يَخْرُجُ فِي أَظْفَارِي ثُمَّ أَعْطَيْتُ فَضْلِي ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏قَالُوا فَمَا ‏ ‏أَوَّلْتَهُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ الْعِلْمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ad55eef4-5c84-529a-a434-1fefa3cb0d0e', '5cb5e738-220a-4267-901a-841c834b5d56', '81', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ فِي حَجَّةِ الْوَدَاعِ ‏ ‏بِمِنًى ‏ ‏لِلنَّاسِ يَسْأَلُونَهُ فَجَاءَهُ رَجُلٌ فَقَالَ لَمْ أَشْعُرْ فَحَلَقْتُ قَبْلَ أَنْ أَذْبَحَ فَقَالَ ‏ ‏اذْبَحْ وَلَا حَرَجَ فَجَاءَ آخَرُ فَقَالَ لَمْ ‏ ‏أَشْعُرْ ‏ ‏فَنَحَرْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ ارْمِ وَلَا حَرَجَ فَمَا سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ شَيْءٍ قُدِّمَ وَلَا أُخِّرَ إِلَّا قَالَ افْعَلْ وَلَا حَرَجَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('70e4db5b-fc38-5484-8000-e8a13618a2aa', '5cb5e738-220a-4267-901a-841c834b5d56', '82', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ فِي حَجَّتِهِ فَقَالَ ذَبَحْتُ قَبْلَ أَنْ أَرْمِيَ ‏ ‏فَأَوْمَأَ ‏ ‏بِيَدِهِ قَالَ ‏ ‏وَلَا حَرَجَ قَالَ حَلَقْتُ قَبْلَ أَنْ أَذْبَحَ ‏ ‏فَأَوْمَأَ ‏ ‏بِيَدِهِ وَلَا حَرَجَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('be692245-cf9e-55e9-b531-6a20edc262a1', '5cb5e738-220a-4267-901a-841c834b5d56', '83', '‏ ‏حَدَّثَنَا ‏ ‏الْمَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَنْظَلَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُقْبَضُ الْعِلْمُ وَيَظْهَرُ الْجَهْلُ وَالْفِتَنُ وَيَكْثُرُ الْهَرْجُ قِيلَ يَا رَسُولَ اللَّهِ وَمَا الْهَرْجُ فَقَالَ هَكَذَا بِيَدِهِ فَحَرَّفَهَا كَأَنَّه يُرِيدُ الْقَتْلَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('005e0f5c-476e-58b3-adcf-2fc4a8633bc6', '5cb5e738-220a-4267-901a-841c834b5d56', '84', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ‏ ‏قَالَتْ ‏ ‏أَتَيْتُ ‏ ‏عَائِشَةَ ‏ ‏وَهِيَ تُصَلِّي فَقُلْتُ مَا شَأْنُ النَّاسِ فَأَشَارَتْ إِلَى السَّمَاءِ فَإِذَا النَّاسُ قِيَامٌ فَقَالَتْ سُبْحَانَ اللَّهِ قُلْتُ آيَةٌ فَأَشَارَتْ بِرَأْسِهَا أَيْ نَعَمْ فَقُمْتُ حَتَّى ‏ ‏تَجَلَّانِي ‏ ‏الْغَشْيُ فَجَعَلْتُ أَصُبُّ عَلَى رَأْسِي الْمَاءَ فَحَمِدَ اللَّهَ عَزَّ وَجَلَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ مَا مِنْ شَيْءٍ لَمْ أَكُنْ أُرِيتُهُ إِلَّا رَأَيْتُهُ فِي مَقَامِي حَتَّى الْجَنَّةُ وَالنَّارُ ‏ ‏فَأُوحِيَ إِلَيَّ أَنَّكُمْ تُفْتَنُونَ فِي قُبُورِكُمْ مِثْلَ ‏ ‏أَوْ قَرِيبَ لَا أَدْرِي أَيَّ ذَلِكَ قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏مِنْ فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏يُقَالُ مَا عِلْمُكَ بِهَذَا الرَّجُلِ فَأَمَّا الْمُؤْمِنُ ‏ ‏أَوْ الْمُوقِنُ لَا أَدْرِي بِأَيِّهِمَا قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏فَيَقُولُ هُوَ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ جَاءَنَا بِالْبَيِّنَاتِ وَالْهُدَى فَأَجَبْنَا وَاتَّبَعْنَا هُوَ ‏ ‏مُحَمَّدٌ ‏ ‏ثَلَاثًا فَيُقَالُ نَمْ صَالِحًا قَدْ عَلِمْنَا إِنْ كُنْتَ لَمُوقِنًا بِهِ وَأَمَّا الْمُنَافِقُ ‏ ‏أَوْ الْمُرْتَابُ لَا أَدْرِي أَيَّ ذَلِكَ قَالَتْ ‏ ‏أَسْمَاءُ ‏ ‏فَيَقُولُ لَا أَدْرِي سَمِعْتُ النَّاسَ يَقُولُونَ شَيْئًا فَقُلْتُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b6952d1d-7e1a-56d9-9d8b-9719466692ba', '5cb5e738-220a-4267-901a-841c834b5d56', '85', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أُتَرْجِمُ بَيْنَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَبَيْنَ النَّاسِ فَقَالَ إِنَّ ‏ ‏وَفْدَ عَبْدِ الْقَيْسِ ‏ ‏أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْ الْوَفْدُ ‏ ‏أَوْ مَنْ الْقَوْمُ ‏ ‏قَالُوا ‏ ‏رَبِيعَةُ ‏ ‏فَقَالَ مَرْحَبًا بِالْقَوْمِ ‏ ‏أَوْ بِالْوَفْدِ ‏ ‏غَيْرَ خَزَايَا وَلَا نَدَامَى قَالُوا إِنَّا ‏ ‏نَأْتِيكَ مِنْ ‏ ‏شُقَّةٍ ‏ ‏بَعِيدَةٍ وَبَيْنَنَا وَبَيْنَكَ هَذَا الْحَيُّ مِنْ كُفَّارِ ‏ ‏مُضَرَ ‏ ‏وَلَا نَسْتَطِيعُ أَنْ نَأْتِيَكَ إِلَّا فِي شَهْرٍ حَرَامٍ فَمُرْنَا بِأَمْرٍ نُخْبِرُ بِهِ مَنْ وَرَاءَنَا نَدْخُلُ بِهِ الْجَنَّةَ ‏ ‏فَأَمَرَهُمْ بِأَرْبَعٍ وَنَهَاهُمْ عَنْ أَرْبَعٍ أَمَرَهُمْ بِالْإِيمَانِ بِاللَّهِ عَزَّ وَجَلَّ وَحْدَهُ قَالَ هَلْ تَدْرُونَ مَا الْإِيمَانُ بِاللَّهِ وَحْدَهُ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ وَإِقَامُ الصَّلَاةِ وَإِيتَاءُ الزَّكَاةِ وَصَوْمُ رَمَضَانَ وَتُعْطُوا الْخُمُسَ مِنْ الْمَغْنَمِ وَنَهَاهُمْ عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏رُبَّمَا قَالَ ‏ ‏النَّقِيرِ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏الْمُقَيَّرِ ‏ ‏قَالَ احْفَظُوهُ وَأَخْبِرُوهُ مَنْ وَرَاءَكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ebabc29b-698a-506d-bbf5-56ba37db55ac', '5cb5e738-220a-4267-901a-841c834b5d56', '86', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ أَبُو الْحَسَنِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُمَرُ بْنُ سَعِيدِ بْنِ أَبِي حُسَيْنٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ الْحَارِثِ ‏ ‏أَنَّهُ تَزَوَّجَ ‏ ‏ابْنَةً ‏ ‏لِأَبِي إِهَابِ بْنِ عَزِيزٍ ‏ ‏فَأَتَتْهُ امْرَأَةٌ فَقَالَتْ إِنِّي قَدْ أَرْضَعْتُ ‏ ‏عُقْبَةَ ‏ ‏وَالَّتِي تَزَوَّجَ فَقَالَ لَهَا ‏ ‏عُقْبَةُ ‏ ‏مَا أَعْلَمُ أَنَّكِ أَرْضَعْتِنِي وَلَا أَخْبَرْتِنِي فَرَكِبَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَسَأَلَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ وَقَدْ قِيلَ فَفَارَقَهَا ‏ ‏عُقْبَةُ ‏ ‏وَنَكَحَتْ ‏ ‏زَوْجًا ‏ ‏غَيْرَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7f54f64f-f3ce-588d-8daf-fb692021c9f4', '5cb5e738-220a-4267-901a-841c834b5d56', '87', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏ح ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏وَقَالَ ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي ثَوْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَنَا ‏ ‏وَجَارٌ لِي ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فِي ‏ ‏بَنِي أُمَيَّةَ بْنِ زَيْدٍ ‏ ‏وَهِيَ مِنْ ‏ ‏عَوَالِي الْمَدِينَةِ ‏ ‏وَكُنَّا نَتَنَاوَبُ النُّزُولَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْزِلُ يَوْمًا وَأَنْزِلُ يَوْمًا فَإِذَا نَزَلْتُ جِئْتُهُ بِخَبَرِ ذَلِكَ الْيَوْمِ مِنْ الْوَحْيِ وَغَيْرِهِ وَإِذَا نَزَلَ فَعَلَ مِثْلَ ذَلِكَ فَنَزَلَ صَاحِبِي الْأَنْصَارِيُّ يَوْمَ نَوْبَتِهِ فَضَرَبَ بَابِي ضَرْبًا شَدِيدًا فَقَالَ أَثَمَّ هُوَ فَفَزِعْتُ فَخَرَجْتُ إِلَيْهِ فَقَالَ قَدْ حَدَثَ أَمْرٌ عَظِيمٌ قَالَ فَدَخَلْتُ عَلَى ‏ ‏حَفْصَةَ ‏ ‏فَإِذَا هِيَ تَبْكِي فَقُلْتُ طَلَّقَكُنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ لَا أَدْرِي ثُمَّ دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ وَأَنَا قَائِمٌ أَطَلَّقْتَ نِسَاءَكَ قَالَ ‏ ‏لَا فَقُلْتُ اللَّهُ أَكْبَرُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c6932f5f-7e78-5dd8-b2f6-b5fa9127ac24', '5cb5e738-220a-4267-901a-841c834b5d56', '88', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏رَجُلٌ ‏ ‏يَا رَسُولَ اللَّهِ لَا أَكَادُ أُدْرِكُ الصَّلَاةَ مِمَّا يُطَوِّلُ بِنَا فُلَانٌ فَمَا رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَوْعِظَةٍ أَشَدَّ غَضَبًا مِنْ يَوْمِئِذٍ فَقَالَ ‏ ‏أَيُّهَا النَّاسُ إِنَّكُمْ مُنَفِّرُونَ فَمَنْ صَلَّى بِالنَّاسِ فَلْيُخَفِّفْ فَإِنَّ فِيهِمْ الْمَرِيضَ وَالضَّعِيفَ وَذَا الْحَاجَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2205ea0d-ba5a-5d3f-a0f1-fb2e178409fc', '5cb5e738-220a-4267-901a-841c834b5d56', '89', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو الْعَقَدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ الْمَدِينِيُّ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏مَوْلَى ‏ ‏الْمُنْبَعِثِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلَهُ ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏اللُّقَطَةِ ‏ ‏فَقَالَ ‏ ‏اعْرِفْ ‏ ‏وِكَاءَهَا ‏ ‏أَوْ قَالَ وِعَاءَهَا ‏ ‏وَعِفَاصَهَا ‏ ‏ثُمَّ عَرِّفْهَا سَنَةً ثُمَّ اسْتَمْتِعْ بِهَا فَإِنْ جَاءَ رَبُّهَا فَأَدِّهَا إِلَيْهِ قَالَ ‏ ‏فَضَالَّةُ ‏ ‏الْإِبِلِ فَغَضِبَ حَتَّى احْمَرَّتْ وَجْنَتَاهُ ‏ ‏أَوْ قَالَ احْمَرَّ وَجْهُهُ ‏ ‏فَقَالَ وَمَا لَكَ وَلَهَا مَعَهَا سِقَاؤُهَا وَحِذَاؤُهَا تَرِدُ الْمَاءَ وَتَرْعَى الشَّجَرَ فَذَرْهَا حَتَّى يَلْقَاهَا رَبُّهَا قَالَ ‏ ‏فَضَالَّةُ ‏ ‏الْغَنَمِ قَالَ لَكَ أَوْ لِأَخِيكَ أَوْ لِلذِّئْبِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('98894c60-189b-5b09-8a61-be1bb5fe71e1', '5cb5e738-220a-4267-901a-841c834b5d56', '90', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏بُرَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَشْيَاءَ كَرِهَهَا فَلَمَّا أُكْثِرَ عَلَيْهِ غَضِبَ ثُمَّ قَالَ لِلنَّاسِ ‏ ‏سَلُونِي عَمَّا شِئْتُمْ قَالَ ‏ ‏رَجُلٌ ‏ ‏مَنْ أَبِي قَالَ أَبُوكَ ‏ ‏حُذَافَةُ ‏ ‏فَقَامَ ‏ ‏آخَرُ ‏ ‏فَقَالَ مَنْ أَبِي يَا رَسُولَ اللَّهِ فَقَالَ أَبُوكَ ‏ ‏سَالِمٌ ‏ ‏مَوْلَى ‏ ‏شَيْبَةَ ‏ ‏فَلَمَّا رَأَى ‏ ‏عُمَرُ ‏ ‏مَا فِي وَجْهِهِ قَالَ يَا رَسُولَ اللَّهِ إِنَّا نَتُوبُ إِلَى اللَّهِ عَزَّ وَجَلَّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('29bb9e0a-f218-5721-9e67-0afd71b354d7', '5cb5e738-220a-4267-901a-841c834b5d56', '91', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ فَقَامَ ‏ ‏عَبْدُ اللَّهِ بْنُ حُذَافَةَ ‏ ‏فَقَالَ مَنْ أَبِي فَقَالَ ‏ ‏أَبُوكَ ‏ ‏حُذَافَةُ ‏ ‏ثُمَّ أَكْثَرَ أَنْ يَقُولَ سَلُونِي فَبَرَكَ ‏ ‏عُمَرُ ‏ ‏عَلَى رُكْبَتَيْهِ فَقَالَ رَضِينَا بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيًّا فَسَكَتَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('81eaf7f9-91e2-544a-9c1a-e265c3508ac3', '5cb5e738-220a-4267-901a-841c834b5d56', '92', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثُمَامَةُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏إِذَا سَلَّمَ سَلَّمَ ثَلَاثًا وَإِذَا تَكَلَّمَ بِكَلِمَةٍ أَعَادَهَا ثَلَاثًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2de50560-ba66-5440-905e-49f498aebd1b', '5cb5e738-220a-4267-901a-841c834b5d56', '93', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ عَبْدِ اللَّهِ الصَّفَارُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثُمَامَةُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏إِذَا تَكَلَّمَ بِكَلِمَةٍ أَعَادَهَا ثَلَاثًا حَتَّى تُفْهَمَ عَنْهُ وَإِذَا أَتَى عَلَى قَوْمٍ فَسَلَّمَ عَلَيْهِمْ سَلَّمَ عَلَيْهِمْ ثَلَاثًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b452edf8-176d-5bed-882d-4b1b20092eb6', '5cb5e738-220a-4267-901a-841c834b5d56', '94', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏تَخَلَّفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ سَافَرْنَاهُ فَأَدْرَكَنَا وَقَدْ أَرْهَقْنَا الصَّلَاةَ صَلَاةَ الْعَصْرِ وَنَحْنُ نَتَوَضَّأُ فَجَعَلْنَا نَمْسَحُ عَلَى أَرْجُلِنَا فَنَادَى بِأَعْلَى صَوْتِهِ ‏ ‏وَيْلٌ لِلْأَعْقَابِ مِنْ النَّارِ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ae258930-5e5e-52c3-bf00-5a1556c8474f', '5cb5e738-220a-4267-901a-841c834b5d56', '95', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ سَلَامٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُحَارِبِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَالِحُ بْنُ حَيَّانَ ‏ ‏قَالَ قَالَ ‏ ‏عَامِرٌ الشَّعْبِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةٌ لَهُمْ أَجْرَانِ رَجُلٌ مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏آمَنَ بِنَبِيِّهِ وَآمَنَ ‏ ‏بِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْعَبْدُ الْمَمْلُوكُ إِذَا أَدَّى حَقَّ اللَّهِ وَحَقَّ مَوَالِيهِ وَرَجُلٌ كَانَتْ عِنْدَهُ أَمَةٌ فَأَدَّبَهَا فَأَحْسَنَ تَأْدِيبَهَا وَعَلَّمَهَا فَأَحْسَنَ تَعْلِيمَهَا ثُمَّ أَعْتَقَهَا فَتَزَوَّجَهَا فَلَهُ أَجْرَانِ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏عَامِرٌ ‏ ‏أَعْطَيْنَاكَهَا بِغَيْرِ شَيْءٍ قَدْ كَانَ يُرْكَبُ فِيمَا دُونَهَا إِلَى ‏ ‏الْمَدِينَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6c7f9d5a-4ccf-5e9c-bdac-cb34493f2644', '5cb5e738-220a-4267-901a-841c834b5d56', '96', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَطَاءً ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَشْهَدُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ ‏ ‏عَطَاءٌ ‏ ‏أَشْهَدُ عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ وَمَعَهُ ‏ ‏بِلَالٌ ‏ ‏فَظَنَّ أَنَّهُ لَمْ يُسْمِعْ فَوَعَظَهُنَّ وَأَمَرَهُنَّ بِالصَّدَقَةِ فَجَعَلَتْ الْمَرْأَةُ تُلْقِي ‏ ‏الْقُرْطَ ‏ ‏وَالْخَاتَمَ ‏ ‏وَبِلَالٌ ‏ ‏يَأْخُذُ فِي طَرَفِ ثَوْبِهِ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏وَقَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَقَالَ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَشْهَدُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c4dcebf0-2a2f-50c9-bc0e-ad9120e6c6d0', '5cb5e738-220a-4267-901a-841c834b5d56', '97', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ مَنْ أَسْعَدُ النَّاسِ بِشَفَاعَتِكَ يَوْمَ الْقِيَامَةِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ظَنَنْتُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنْ لَا يَسْأَلُنِي عَنْ هَذَا الْحَدِيثِ أَحَدٌ أَوَّلُ مِنْكَ لِمَا رَأَيْتُ مِنْ حِرْصِكَ عَلَى الْحَدِيثِ ‏ ‏أَسْعَدُ النَّاسِ بِشَفَاعَتِي يَوْمَ الْقِيَامَةِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ خَالِصًا مِنْ قَلْبِهِ ‏ ‏أَوْ نَفْسِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d6e1ea4d-0ba2-51f5-be34-d27e88746b06', '5cb5e738-220a-4267-901a-841c834b5d56', '98', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي أُوَيْسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ لَا يَقْبِضُ الْعِلْمَ ‏ ‏انْتِزَاعًا ‏ ‏يَنْتَزِعُهُ مِنْ الْعِبَادِ وَلَكِنْ يَقْبِضُ الْعِلْمَ ‏ ‏بِقَبْضِ ‏ ‏الْعُلَمَاءِ حَتَّى إِذَا لَمْ يُبْقِ عَالِمًا اتَّخَذَ النَّاسُ رُءُوسًا جُهَّالًا فَسُئِلُوا فَأَفْتَوْا بِغَيْرِ عِلْمٍ فَضَلُّوا وَأَضَلُّوا ‏ ‏قَالَ ‏ ‏الْفِرَبْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّاسٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏نَحْوَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2b7f2f73-602c-5a0a-ae23-9964bfb5b582', '5cb5e738-220a-4267-901a-841c834b5d56', '99', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ الْأَصْبَهَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَالِحٍ ذَكْوَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَتْ النِّسَاءُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَلَبَنَا ‏ ‏عَلَيْكَ الرِّجَالُ فَاجْعَلْ لَنَا يَوْمًا مِنْ نَفْسِكَ فَوَعَدَهُنَّ يَوْمًا لَقِيَهُنَّ فِيهِ فَوَعَظَهُنَّ وَأَمَرَهُنَّ فَكَانَ فِيمَا قَالَ لَهُنَّ ‏ ‏مَا مِنْكُنَّ امْرَأَةٌ ‏ ‏تُقَدِّمُ ‏ ‏ثَلَاثَةً مِنْ وَلَدِهَا إِلَّا كَانَ لَهَا حِجَابًا مِنْ النَّارِ فَقَالَتْ امْرَأَةٌ وَاثْنَتَيْنِ فَقَالَ وَاثْنَتَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَذَا ‏ ‏وَعَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَصْبَهَانِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏ثَلَاثَةً لَمْ يَبْلُغُوا ‏ ‏الْحِنْثَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c1643cf9-742c-570c-93d9-437593c416d7', '5cb5e738-220a-4267-901a-841c834b5d56', '100', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي مَرْيَمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏نَافِعُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ لَا تَسْمَعُ شَيْئًا لَا تَعْرِفُهُ إِلَّا ‏ ‏رَاجَعَتْ ‏ ‏فِيهِ حَتَّى تَعْرِفَهُ وَأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حُوسِبَ عُذِّبَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ أَوَلَيْسَ يَقُولُ اللَّهُ تَعَالَى ‏ { ‏فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا ‏} ‏قَالَتْ فَقَالَ إِنَّمَا ذَلِكِ ‏ ‏الْعَرْضُ ‏ ‏وَلَكِنْ مَنْ نُوقِشَ الْحِسَابَ يَهْلِكْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1311d87c-f732-5ac2-8656-7efb6e421e18', '5cb5e738-220a-4267-901a-841c834b5d56', '101', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ هُوَ ابْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعَمْرِو بْنِ سَعِيدٍ ‏ ‏وَهُوَ يَبْعَثُ ‏ ‏الْبُعُوثَ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏ائْذَنْ لِي أَيُّهَا الْأَمِيرُ أُحَدِّثْكَ قَوْلًا قَامَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْغَدَ مِنْ يَوْمِ الْفَتْحِ سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي وَأَبْصَرَتْهُ عَيْنَايَ حِينَ تَكَلَّمَ بِهِ حَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ ‏ ‏إِنَّ ‏ ‏مَكَّةَ ‏ ‏حَرَّمَهَا اللَّهُ وَلَمْ يُحَرِّمْهَا النَّاسُ فَلَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ ‏ ‏يَسْفِكَ ‏ ‏بِهَا دَمًا وَلَا ‏ ‏يَعْضِدَ ‏ ‏بِهَا شَجَرَةً فَإِنْ أَحَدٌ ‏ ‏تَرَخَّصَ ‏ ‏لِقِتَالِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا فَقُولُوا إِنَّ اللَّهَ قَدْ أَذِنَ لِرَسُولِهِ وَلَمْ يَأْذَنْ لَكُمْ وَإِنَّمَا أَذِنَ لِي فِيهَا سَاعَةً مِنْ نَهَارٍ ثُمَّ عَادَتْ حُرْمَتُهَا الْيَوْمَ كَحُرْمَتِهَا بِالْأَمْسِ وَلْيُبَلِّغْ الشَّاهِدُ الْغَائِبَ فَقِيلَ ‏ ‏لِأَبِي شُرَيْحٍ ‏ ‏مَا قَالَ ‏ ‏عَمْرٌو ‏ ‏قَالَ أَنَا أَعْلَمُ مِنْكَ يَا ‏ ‏أَبَا شُرَيْحٍ ‏ ‏لَا يُعِيذُ عَاصِيًا وَلَا فَارًّا ‏ ‏بِدَمٍ ‏ ‏وَلَا فَارًّا ‏ ‏بِخَرْبَةٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b18ddf87-2c71-5a13-8aa4-135ec7c406fa', '5cb5e738-220a-4267-901a-841c834b5d56', '102', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الْوَهَّابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏ذُكِرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَأَحْسِبُهُ قَالَ وَأَعْرَاضَكُمْ ‏ ‏عَلَيْكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا أَلَا لِيُبَلِّغ الشَّاهِدُ مِنْكُمْ الْغَائِبَ وَكَانَ ‏ ‏مُحَمَّدٌ ‏ ‏يَقُولُ صَدَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ذَلِكَ أَلَا هَلْ بَلَّغْتُ مَرَّتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('89535bbd-2f22-5363-a6fe-b976ab410a52', '5cb5e738-220a-4267-901a-841c834b5d56', '103', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْجَعْدِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْصُورٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رِبْعِيَّ بْنَ حِرَاشٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَلِيًّا ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْذِبُوا عَلَيَّ فَإِنَّهُ مَنْ كَذَبَ عَلَيَّ فَلْيَلِجْ النَّارَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dc863ab3-036d-550e-af2a-2a188f9f89b2', '5cb5e738-220a-4267-901a-841c834b5d56', '104', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِلزُّبَيْرِ ‏ ‏إِنِّي لَا أَسْمَعُكَ تُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا يُحَدِّثُ فُلَانٌ وَفُلَانٌ قَالَ أَمَا إِنِّي لَمْ أُفَارِقْهُ وَلَكِنْ سَمِعْتُهُ يَقُولُ ‏ ‏مَنْ كَذَبَ عَلَيَّ ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4a2c5029-eb0c-5a5e-8987-f5570f014ffc', '5cb5e738-220a-4267-901a-841c834b5d56', '105', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏إِنَّهُ لَيَمْنَعُنِي أَنْ أُحَدِّثَكُمْ حَدِيثًا كَثِيرًا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَعَمَّدَ عَلَيَّ كَذِبًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('328a7bf7-2fa6-519e-b7b0-f2ec2d60948e', '5cb5e738-220a-4267-901a-841c834b5d56', '106', '‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ يَقُلْ عَلَيَّ مَا لَمْ أَقُلْ ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('459d0095-3e22-5d88-98c3-863463b2117f', '5cb5e738-220a-4267-901a-841c834b5d56', '107', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكْتَنُوا بِكُنْيَتِي وَمَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فَإِنَّ الشَّيْطَانَ لَا ‏ ‏يَتَمَثَّلُ ‏ ‏فِي صُورَتِي وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9d7446fd-7d52-59db-8073-50cf328b3514', '5cb5e738-220a-4267-901a-841c834b5d56', '108', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَامٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي جُحَيْفَةَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏هَلْ عِنْدَكُمْ كِتَابٌ قَالَ ‏ ‏لَا إِلَّا كِتَابُ اللَّهِ أَوْ فَهْمٌ أُعْطِيَهُ رَجُلٌ مُسْلِمٌ أَوْ مَا فِي هَذِهِ الصَّحِيفَةِ قَالَ قُلْتُ فَمَا فِي هَذِهِ الصَّحِيفَةِ قَالَ ‏ ‏الْعَقْلُ ‏ ‏وَفَكَاكُ ‏ ‏الْأَسِيرِ وَلَا يُقْتَلُ مُسْلِمٌ بِكَافِرٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ad2392d3-27a3-5980-a51e-0c6b37cf5e13', '5cb5e738-220a-4267-901a-841c834b5d56', '109', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏خُزَاعَةَ ‏ ‏قَتَلُوا رَجُلًا مِنْ ‏ ‏بَنِي لَيْثٍ ‏ ‏عَامَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏بِقَتِيلٍ ‏ ‏مِنْهُمْ قَتَلُوهُ فَأُخْبِرَ بِذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَكِبَ ‏ ‏رَاحِلَتَهُ ‏ ‏فَخَطَبَ فَقَالَ ‏ ‏إِنَّ اللَّهَ ‏ ‏حَبَسَ ‏ ‏عَنْ ‏ ‏مَكَّةَ ‏ ‏الْقَتْلَ ‏ ‏أَوْ الْفِيلَ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏كَذَا ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏وَاجْعَلُوهُ عَلَى الشَّكِّ الْفِيلَ أَوْ الْقَتْلَ ‏ ‏وَغَيْرُهُ ‏ ‏يَقُولُ ‏ ‏الْفِيلَ ‏ ‏وَسَلَّطَ عَلَيْهِمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمُؤْمِنِينَ أَلَا وَإِنَّهَا لَمْ تَحِلَّ لِأَحَدٍ قَبْلِي وَلَمْ تَحِلَّ لِأَحَدٍ بَعْدِي أَلَا وَإِنَّهَا حَلَّتْ لِي سَاعَةً مِنْ نَهَارٍ أَلَا وَإِنَّهَا سَاعَتِي هَذِهِ حَرَامٌ لَا ‏ ‏يُخْتَلَى ‏ ‏شَوْكُهَا وَلَا ‏ ‏يُعْضَدُ ‏ ‏شَجَرُهَا وَلَا ‏ ‏تُلْتَقَطُ ‏ ‏سَاقِطَتُهَا ‏ ‏إِلَّا ‏ ‏لِمُنْشِدٍ ‏ ‏فَمَنْ قُتِلَ فَهُوَ بِخَيْرِ ‏ ‏النَّظَرَيْنِ ‏ ‏إِمَّا أَنْ ‏ ‏يُعْقَلَ ‏ ‏وَإِمَّا أَنْ ‏ ‏يُقَادَ ‏ ‏أَهْلُ الْقَتِيلِ فَجَاءَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ اكْتُبْ لِي يَا رَسُولَ اللَّهِ فَقَالَ اكْتُبُوا لِأَبِي فُلَانٍ فَقَالَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏إِلَّا ‏ ‏الْإِذْخِرَ ‏ ‏يَا رَسُولَ اللَّهِ فَإِنَّا نَجْعَلُهُ فِي بُيُوتِنَا وَقُبُورِنَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا ‏ ‏الْإِذْخِرَ ‏ ‏إِلَّا ‏ ‏الْإِذْخِرَ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏يُقَالُ ‏ ‏يُقَادُ ‏ ‏بِالْقَافِ فَقِيلَ ‏ ‏لِأَبِي عَبْدِ اللَّهِ ‏ ‏أَيُّ شَيْءٍ كَتَبَ لَهُ قَالَ كَتَبَ لَهُ هَذِهِ الْخُطْبَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ab480c81-88e7-5d61-8cac-86ea26b7290f', '5cb5e738-220a-4267-901a-841c834b5d56', '110', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرٌو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏وَهْبُ بْنُ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَدٌ أَكْثَرَ حَدِيثًا عَنْهُ مِنِّي إِلَّا مَا كَانَ مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏فَإِنَّهُ كَانَ يَكْتُبُ وَلَا أَكْتُبُ ‏ ‏تَابَعَهُ ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('36be97ee-4ad0-58c7-9472-65e0e50b36ae', '5cb5e738-220a-4267-901a-841c834b5d56', '111', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا اشْتَدَّ بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَعُهُ قَالَ ‏ ‏ائْتُونِي بِكِتَابٍ أَكْتُبْ لَكُمْ كِتَابًا لَا تَضِلُّوا بَعْدَهُ قَالَ ‏ ‏عُمَرُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَلَبَهُ ‏ ‏الْوَجَعُ وَعِنْدَنَا كِتَابُ اللَّهِ حَسْبُنَا فَاخْتَلَفُوا وَكَثُرَ ‏ ‏اللَّغَطُ ‏ ‏قَالَ قُومُوا عَنِّي وَلَا يَنْبَغِي عِنْدِي التَّنَازُعُ ‏ ‏فَخَرَجَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏الرَّزِيَّةَ ‏ ‏كُلَّ ‏ ‏الرَّزِيَّةِ ‏ ‏مَا حَالَ بَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ كِتَابِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5925495b-f107-516b-a074-63af60cb1018', '5cb5e738-220a-4267-901a-841c834b5d56', '112', '‏ ‏حَدَّثَنَا ‏ ‏صَدَقَةُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏هِنْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏وَعَمْرٍو ‏ ‏وَيَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏هِنْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏اسْتَيْقَظَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَقَالَ ‏ ‏سُبْحَانَ اللَّهِ مَاذَا أُنْزِلَ اللَّيْلَةَ مِنْ الْفِتَنِ وَمَاذَا فُتِحَ مِنْ الْخَزَائِنِ أَيْقِظُوا ‏ ‏صَوَاحِبَاتِ الْحُجَرِ ‏ ‏فَرُبَّ ‏ ‏كَاسِيَةٍ ‏ ‏فِي الدُّنْيَا عَارِيَةٍ فِي الْآخِرَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('224c4c9a-59d2-5fc7-aec8-462bee5fb4bd', '5cb5e738-220a-4267-901a-841c834b5d56', '113', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عُفَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ خَالِدِ بْنِ مُسَافِرٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏وَأَبِي بَكْرِ بْنِ سُلَيْمَانَ بْنِ أَبِي حَثْمَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ فِي آخِرِ حَيَاتِهِ فَلَمَّا سَلَّمَ قَامَ فَقَالَ ‏ ‏أَرَأَيْتَكُمْ لَيْلَتَكُمْ هَذِهِ فَإِنَّ رَأْسَ مِائَةِ سَنَةٍ مِنْهَا لَا يَبْقَى مِمَّنْ هُوَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('631d35f0-20f3-5d30-b6a7-b2cac1ab2e62', '5cb5e738-220a-4267-901a-841c834b5d56', '114', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بِتُّ فِي بَيْتِ خَالَتِي ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَهَا فِي لَيْلَتِهَا فَصَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ ثُمَّ جَاءَ إِلَى مَنْزِلِهِ فَصَلَّى أَرْبَعَ رَكَعَاتٍ ثُمَّ نَامَ ثُمَّ قَامَ ثُمَّ قَالَ ‏ ‏نَامَ ‏ ‏الْغُلَيِّمُ ‏ ‏أَوْ كَلِمَةً تُشْبِهُهَا ‏ ‏ثُمَّ قَامَ فَقُمْتُ عَنْ يَسَارِهِ فَجَعَلَنِي عَنْ يَمِينِهِ فَصَلَّى خَمْسَ رَكَعَاتٍ ثُمَّ صَلَّى رَكْعَتَيْنِ ثُمَّ نَامَ حَتَّى سَمِعْتُ ‏ ‏غَطِيطَهُ ‏ ‏أَوْ ‏ ‏خَطِيطَهُ ‏ ‏ثُمَّ خَرَجَ إِلَى الصَّلَاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('df5a736f-d9ba-5edd-8e91-76c8cb42f137', '5cb5e738-220a-4267-901a-841c834b5d56', '115', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنَّ النَّاسَ يَقُولُونَ أَكْثَرَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَلَوْلَا آيَتَانِ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُ حَدِيثًا ثُمَّ يَتْلُو ‏ { ‏إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنْ الْبَيِّنَاتِ وَالْهُدَى ‏ ‏إِلَى قَوْلِهِ ‏ ‏الرَّحِيمُ ‏} ‏إِنَّ إِخْوَانَنَا مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏كَانَ يَشْغَلُهُمْ ‏ ‏الصَّفْقُ ‏ ‏بِالْأَسْوَاقِ وَإِنَّ إِخْوَانَنَا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏كَانَ يَشْغَلُهُمْ الْعَمَلُ فِي أَمْوَالِهِمْ وَإِنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ يَلْزَمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشِبَعِ بَطْنِهِ وَيَحْضُرُ مَا لَا يَحْضُرُونَ وَيَحْفَظُ مَا لَا يَحْفَظُونَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ae89f15d-f627-505a-8f5b-6a41bf0f1127', '5cb5e738-220a-4267-901a-841c834b5d56', '116', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ أَبِي بَكْرٍ أَبُو مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ قُلْتُ ‏ ‏يَا رَسُولَ اللَّهِ إِنِّي أَسْمَعُ مِنْكَ حَدِيثًا كَثِيرًا أَنْسَاهُ قَالَ ‏ ‏ابْسُطْ رِدَاءَكَ فَبَسَطْتُهُ قَالَ فَغَرَفَ بِيَدَيْهِ ثُمَّ قَالَ ضُمَّهُ فَضَمَمْتُهُ فَمَا نَسِيتُ شَيْئًا بَعْدَهُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي فُدَيْكٍ ‏ ‏بِهَذَا ‏ ‏أَوْ قَالَ غَرَفَ بِيَدِهِ فِيهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d18452b1-1509-59fc-85a2-df922ece91fb', '5cb5e738-220a-4267-901a-841c834b5d56', '117', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَخِي ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏حَفِظْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وِعَاءَيْنِ فَأَمَّا أَحَدُهُمَا فَبَثَثْتُهُ وَأَمَّا الْآخَرُ فَلَوْ بَثَثْتُهُ قُطِعَ هَذَا الْبُلْعُومُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('08181e6b-a868-5b3d-bc3e-544e1188a28d', '5cb5e738-220a-4267-901a-841c834b5d56', '118', '‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ مُدْرِكٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ فِي حَجَّةِ الْوَدَاعِ اسْتَنْصِتْ النَّاسَ فَقَالَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5fef3a56-f63a-5476-b3ad-4154e25c3e00', '5cb5e738-220a-4267-901a-841c834b5d56', '119', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرٌو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏إِنَّ ‏ ‏نَوْفًا الْبَكَالِيَّ ‏ ‏يَزْعُمُ أَنَّ ‏ ‏مُوسَى ‏ ‏لَيْسَ ‏ ‏بِمُوسَى ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏إِنَّمَا هُوَ ‏ ‏مُوسَى ‏ ‏آخَرُ فَقَالَ كَذَبَ عَدُوُّ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ ‏ ‏مُوسَى ‏ ‏النَّبِيُّ خَطِيبًا فِي ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَسُئِلَ أَيُّ النَّاسِ أَعْلَمُ فَقَالَ أَنَا أَعْلَمُ فَعَتَبَ اللَّهُ عَلَيْهِ إِذْ لَمْ يَرُدَّ الْعِلْمَ إِلَيْهِ فَأَوْحَى اللَّهُ إِلَيْهِ أَنَّ عَبْدًا مِنْ عِبَادِي ‏ ‏بِمَجْمَعِ الْبَحْرَيْنِ ‏ ‏هُوَ أَعْلَمُ مِنْكَ قَالَ يَا رَبِّ وَكَيْفَ بِهِ فَقِيلَ لَهُ احْمِلْ حُوتًا فِي ‏ ‏مِكْتَلٍ ‏ ‏فَإِذَا فَقَدْتَهُ فَهُوَ ثَمَّ فَانْطَلَقَ وَانْطَلَقَ بِفَتَاهُ ‏ ‏يُوشَعَ بْنِ نُونٍ ‏ ‏وَحَمَلَا حُوتًا فِي ‏ ‏مِكْتَلٍ ‏ ‏حَتَّى كَانَا عِنْدَ الصَّخْرَةِ وَضَعَا رُءُوسَهُمَا وَنَامَا ‏ ‏فَانْسَلَّ ‏ ‏الْحُوتُ مِنْ ‏ ‏الْمِكْتَلِ ‏ { ‏فَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ ‏ ‏سَرَبًا ‏ } ‏وَكَانَ ‏ ‏لِمُوسَى ‏ ‏وَفَتَاهُ عَجَبًا فَانْطَلَقَا بَقِيَّةَ لَيْلَتِهِمَا وَيَوْمَهُمَا فَلَمَّا أَصْبَحَ قَالَ ‏ ‏مُوسَى ‏ ‏لِفَتَاهُ ‏ { ‏آتِنَا غَدَاءَنَا لَقَدْ لَقِينَا مِنْ سَفَرِنَا هَذَا ‏ ‏نَصَبًا ‏ } ‏وَلَمْ يَجِدْ ‏ ‏مُوسَى ‏ ‏مَسًّا مِنْ ‏ ‏النَّصَبِ ‏ ‏حَتَّى جَاوَزَ الْمَكَانَ الَّذِي أُمِرَ بِهِ فَقَالَ لَهُ فَتَاهُ ‏ { ‏أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ فَإِنِّي نَسِيتُ الْحُوتَ وَمَا ‏ ‏أَنْسَانِيهِ ‏ ‏إِلَّا الشَّيْطَانُ ‏} ‏قَالَ ‏ ‏مُوسَى ‏ { ‏ذَلِكَ مَا كُنَّا ‏ ‏نَبْغِي ‏ ‏فَارْتَدَّا عَلَى آثَارِهِمَا قَصَصًا ‏} ‏فَلَمَّا انْتَهَيَا إِلَى الصَّخْرَةِ إِذَا رَجُلٌ مُسَجًّى بِثَوْبٍ ‏ ‏أَوْ قَالَ تَسَجَّى بِثَوْبِهِ ‏ ‏فَسَلَّمَ ‏ ‏مُوسَى ‏ ‏فَقَالَ ‏ ‏الْخَضِرُ ‏ ‏وَأَنَّى بِأَرْضِكَ السَّلَامُ فَقَالَ أَنَا ‏ ‏مُوسَى ‏ ‏فَقَالَ ‏ ‏مُوسَى ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏قَالَ نَعَمْ قَالَ ‏ { ‏هَلْ أَتَّبِعُكَ عَلَى أَنْ ‏ ‏تُعَلِّمَنِي ‏ ‏مِمَّا عُلِّمْتَ ‏ ‏رَشَدًا ‏ } ‏قَالَ ‏ { ‏إِنَّكَ لَنْ تَسْتَطِيعَ ‏ ‏مَعِيَ صَبْرًا ‏} ‏يَا ‏ ‏مُوسَى ‏ ‏إِنِّي عَلَى عِلْمٍ مِنْ عِلْمِ اللَّهِ عَلَّمَنِيهِ لَا تَعْلَمُهُ أَنْتَ وَأَنْتَ عَلَى عِلْمٍ عَلَّمَكَهُ لَا أَعْلَمُهُ ‏ { ‏قَالَ سَتَجِدُنِي إِنْ شَاءَ اللَّهُ صَابِرًا وَلَا أَعْصِي لَكَ أَمْرًا ‏} ‏فَانْطَلَقَا يَمْشِيَانِ عَلَى سَاحِلِ الْبَحْرِ لَيْسَ لَهُمَا سَفِينَةٌ فَمَرَّتْ بِهِمَا سَفِينَةٌ فَكَلَّمُوهُمْ أَنْ يَحْمِلُوهُمَا فَعُرِفَ ‏ ‏الْخَضِرُ ‏ ‏فَحَمَلُوهُمَا بِغَيْرِ نَوْلٍ فَجَاءَ عُصْفُورٌ فَوَقَعَ عَلَى حَرْفِ السَّفِينَةِ فَنَقَرَ نَقْرَةً أَوْ نَقْرَتَيْنِ فِي الْبَحْرِ فَقَالَ ‏ ‏الْخَضِرُ ‏ ‏يَا ‏ ‏مُوسَى ‏ ‏مَا نَقَصَ عِلْمِي وَعِلْمُكَ مِنْ عِلْمِ اللَّهِ إِلَّا كَنَقْرَةِ هَذَا الْعُصْفُورِ فِي الْبَحْرِ فَعَمَدَ ‏ ‏الْخَضِرُ ‏ ‏إِلَى لَوْحٍ مِنْ أَلْوَاحِ السَّفِينَةِ فَنَزَعَهُ فَقَالَ ‏ ‏مُوسَى ‏ ‏قَوْمٌ حَمَلُونَا بِغَيْرِ ‏ ‏نَوْلٍ ‏ ‏عَمَدْتَ إِلَى سَفِينَتِهِمْ فَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا ‏ { ‏قَالَ أَلَمْ أَقُلْ إِنَّكَ لَنْ تَسْتَطِيعَ ‏ ‏مَعِيَ صَبْرًا قَالَ لَا تُؤَاخِذْنِي بِمَا نَسِيتُ وَلَا تُرْهِقْنِي مِنْ أَمْرِي عُسْرًا ‏} ‏فَكَانَتْ الْأُولَى مِنْ ‏ ‏مُوسَى ‏ ‏نِسْيَانًا فَانْطَلَقَا فَإِذَا غُلَامٌ يَلْعَبُ مَعَ الْغِلْمَانِ فَأَخَذَ ‏ ‏الْخَضِرُ ‏ ‏بِرَأْسِهِ مِنْ أَعْلَاهُ فَاقْتَلَعَ رَأْسَهُ بِيَدِهِ فَقَالَ ‏ ‏مُوسَى ‏ { ‏أَقَتَلْتَ نَفْسًا زَكِيَّةً بِغَيْرِ نَفْسٍ ‏} { ‏قَالَ أَلَمْ أَقُلْ لَكَ إِنَّكَ لَنْ تَسْتَطِيعَ ‏ ‏مَعِيَ صَبْرًا ‏} ‏قَالَ ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏وَهَذَا أَوْكَدُ ‏ { ‏فَانْطَلَقَا حَتَّى إِذَا أَتَيَا أَهْلَ قَرْيَةٍ اسْتَطْعَمَا أَهْلَهَا فَأَبَوْا أَنْ يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَنْ ‏ ‏يَنْقَضَّ ‏ ‏فَأَقَامَهُ ‏} ‏قَالَ ‏ ‏الْخَضِرُ ‏ ‏بِيَدِهِ ‏ ‏فَأَقَامَهُ ‏ ‏فَقَالَ لَهُ ‏ ‏مُوسَى ‏ { ‏لَوْ شِئْتَ لَاتَّخَذْتَ عَلَيْهِ أَجْرًا قَالَ هَذَا فِرَاقُ بَيْنِي وَبَيْنِكَ ‏} ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْحَمُ اللَّهُ ‏ ‏مُوسَى ‏ ‏لَوَدِدْنَا لَوْ صَبَرَ حَتَّى يُقَصَّ عَلَيْنَا مِنْ ‏ ‏أَمْرِهِمَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2251f580-8d56-5ecb-a6a3-0c91f847cd38', '5cb5e738-220a-4267-901a-841c834b5d56', '120', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَا الْقِتَالُ فِي سَبِيلِ اللَّهِ فَإِنَّ أَحَدَنَا يُقَاتِلُ غَضَبًا وَيُقَاتِلُ ‏ ‏حَمِيَّةً ‏ ‏فَرَفَعَ إِلَيْهِ رَأْسَهُ ‏ ‏قَالَ وَمَا رَفَعَ إِلَيْهِ رَأْسَهُ إِلَّا أَنَّهُ كَانَ قَائِمًا ‏ ‏فَقَالَ ‏ ‏مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('325e2731-d407-5361-a7f3-f11be0acc0cd', '5cb5e738-220a-4267-901a-841c834b5d56', '121', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ‏ ‏الْجَمْرَةِ ‏ ‏وَهُوَ يُسْأَلُ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ نَحَرْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ ‏ ‏ارْمِ وَلَا حَرَجَ قَالَ آخَرُ يَا رَسُولَ اللَّهِ حَلَقْتُ قَبْلَ أَنْ أَنْحَرَ قَالَ انْحَرْ وَلَا حَرَجَ فَمَا سُئِلَ عَنْ شَيْءٍ قُدِّمَ وَلَا أُخِّرَ إِلَّا قَالَ افْعَلْ وَلَا حَرَجَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5e064bc2-9ae0-5f72-829e-68963c2c801d', '5cb5e738-220a-4267-901a-841c834b5d56', '122', '‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ حَفْصٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ سُلَيْمَانُ بْنُ مِهْرَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا أَمْشِي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي خَرِبِ ‏ ‏الْمَدِينَةِ ‏ ‏وَهُوَ يَتَوَكَّأُ عَلَى ‏ ‏عَسِيبٍ ‏ ‏مَعَهُ فَمَرَّ بِنَفَرٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ بَعْضُهُمْ لِبَعْضٍ سَلُوهُ عَنْ الرُّوحِ وَقَالَ بَعْضُهُمْ لَا تَسْأَلُوهُ لَا يَجِيءُ فِيهِ بِشَيْءٍ تَكْرَهُونَهُ فَقَالَ بَعْضُهُمْ لَنَسْأَلَنَّهُ فَقَامَ رَجُلٌ مِنْهُمْ فَقَالَ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏مَا الرُّوحُ فَسَكَتَ فَقُلْتُ إِنَّهُ يُوحَى إِلَيْهِ فَقُمْتُ فَلَمَّا ‏ ‏انْجَلَى ‏ ‏عَنْهُ قَالَ ‏ { ‏وَيَسْأَلُونَكَ عَنْ الرُّوحِ قُلْ الرُّوحُ مِنْ أَمْرِ رَبِّي ‏} ‏وَمَا أُوتُوا مِنْ الْعِلْمِ إِلَّا قَلِيلًا ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏هَكَذَا فِي قِرَاءَتِنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('09a207db-79d9-572e-b2df-c57f8545c069', '5cb5e738-220a-4267-901a-841c834b5d56', '123', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏كَانَتْ ‏ ‏عَائِشَةُ ‏ ‏تُسِرُّ إِلَيْكَ كَثِيرًا فَمَا حَدَّثَتْكَ فِي ‏ ‏الْكَعْبَةِ ‏ ‏قُلْتُ قَالَتْ لِي ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏لَوْلَا قَوْمُكِ حَدِيثٌ عَهْدُهُمْ قَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏بِكُفْرٍ لَنَقَضْتُ ‏ ‏الْكَعْبَةَ ‏ ‏فَجَعَلْتُ لَهَا بَابَيْنِ بَابٌ يَدْخُلُ النَّاسُ وَبَابٌ يَخْرُجُونَ ‏ ‏فَفَعَلَهُ ‏ ‏ابْنُ الزُّبَيْرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('39df871c-3e0f-5319-95c5-24c79888dade', '5cb5e738-220a-4267-901a-841c834b5d56', '124', '‏ ‏وَقَالَ ‏ ‏عَلِيٌّ ‏ ‏حَدِّثُوا النَّاسَ بِمَا يَعْرِفُونَ أَتُحِبُّونَ أَنْ يُكَذَّبَ اللَّهُ وَرَسُولُهُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏مَعْرُوفِ بْنِ خَرَّبُوذٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏بِذَلِكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4f3e968a-564f-53e2-b876-0ae77b0e5780', '5cb5e738-220a-4267-901a-841c834b5d56', '125', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمُعاذٌ ‏ ‏رَدِيفُهُ ‏ ‏عَلَى ‏ ‏الرَّحْلِ ‏ ‏قَالَ يَا ‏ ‏مُعَاذَ بْنَ جَبَلٍ ‏ ‏قَالَ لَبَّيْكَ يَا رَسُولَ اللَّهِ وَسَعْدَيْكَ قَالَ يَا ‏ ‏مُعَاذُ ‏ ‏قَالَ لَبَّيْكَ يَا رَسُولَ اللَّهِ وَسَعْدَيْكَ ثَلَاثًا قَالَ ‏ ‏مَا مِنْ أَحَدٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ صِدْقًا مِنْ قَلْبِهِ إِلَّا حَرَّمَهُ اللَّهُ عَلَى النَّارِ قَالَ يَا رَسُولَ اللَّهِ أَفَلَا أُخْبِرُ بِهِ النَّاسَ فَيَسْتَبْشِرُوا قَالَ إِذًا يَتَّكِلُوا وَأَخْبَرَ بِهَا ‏ ‏مُعَاذٌ ‏ ‏عِنْدَ مَوْتِهِ ‏ ‏تَأَثُّمًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bc3127be-fcbd-53ad-89b0-21cf9630d9c0', '5cb5e738-220a-4267-901a-841c834b5d56', '126', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ذُكِرَ لِي ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِمُعَاذِ بْنِ جَبَلٍ ‏ ‏مَنْ لَقِيَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا دَخَلَ الْجَنَّةَ قَالَ أَلَا أُبَشِّرُ النَّاسَ قَالَ لَا إِنِّي أَخَافُ أَنْ يَتَّكِلُوا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d9b760e0-667a-5f0a-b052-3a97e0edb906', '5cb5e738-220a-4267-901a-841c834b5d56', '127', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَامٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏زَيْنَبَ ابْنَةِ أُمِّ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ لَا يَسْتَحْيِي مِنْ الْحَقِّ فَهَلْ عَلَى الْمَرْأَةِ مِنْ غُسْلٍ إِذَا احْتَلَمَتْ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَتْ الْمَاءَ فَغَطَّتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏تَعْنِي وَجْهَهَا وَقَالَتْ يَا رَسُولَ اللَّهِ أَوَتَحْتَلِمُ الْمَرْأَةُ قَالَ نَعَمْ ‏ ‏تَرِبَتْ ‏ ‏يَمِينُكِ فَبِمَ يُشْبِهُهَا وَلَدُهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('514f23af-df5a-56b4-8c0f-462b8d17ff2c', '5cb5e738-220a-4267-901a-841c834b5d56', '128', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ الشَّجَرِ شَجَرَةً لَا يَسْقُطُ وَرَقُهَا وَهِيَ مَثَلُ الْمُسْلِمِ حَدِّثُونِي مَا هِيَ فَوَقَعَ النَّاسُ فِي شَجَرِ الْبَادِيَةِ وَوَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَاسْتَحْيَيْتُ فَقَالُوا يَا رَسُولَ اللَّهِ أَخْبِرْنَا بِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِيَ النَّخْلَةُ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَحَدَّثْتُ أَبِي بِمَا وَقَعَ فِي نَفْسِي فَقَالَ لَأَنْ تَكُونَ قُلْتَهَا أَحَبُّ إِلَيَّ مِنْ أَنْ يَكُونَ لِي كَذَا وَكَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e77861c2-6157-55e8-aef5-ab7d1e16186a', '5cb5e738-220a-4267-901a-841c834b5d56', '129', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دَاوُدَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُنْذِرٍ الْثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏كُنْتُ رَجُلًا ‏ ‏مَذَّاءً ‏ ‏فَأَمَرْتُ ‏ ‏الْمِقْدَادَ بْنَ الْأَسْوَدِ ‏ ‏أَنْ يَسْأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ فَقَالَ ‏ ‏فِيهِ الْوُضُوءُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9eef1812-8c9a-5804-991e-b57a464f5c6f', '5cb5e738-220a-4267-901a-841c834b5d56', '130', '‏ ‏حَدَّثَنِي ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا قَامَ فِي الْمَسْجِدِ فَقَالَ يَا رَسُولَ اللَّهِ مِنْ أَيْنَ تَأْمُرُنَا أَنْ نُهِلَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهِلُّ ‏ ‏أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَيُهِلُّ ‏ ‏أَهْلُ ‏ ‏الشَّأْمِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَيُهِلُّ ‏ ‏أَهْلُ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَيَزْعُمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَيُهِلُّ ‏ ‏أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَقُولُ لَمْ أَفْقَهْ هَذِهِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('13985e75-e603-5d53-aee7-1c8b38b739a6', '5cb5e738-220a-4267-901a-841c834b5d56', '131', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا سَأَلَهُ مَا يَلْبَسُ الْمُحْرِمُ فَقَالَ ‏ ‏لَا يَلْبَسُ الْقَمِيصَ وَلَا الْعِمَامَةَ وَلَا السَّرَاوِيلَ وَلَا ‏ ‏الْبُرْنُسَ ‏ ‏وَلَا ثَوْبًا مَسَّهُ ‏ ‏الْوَرْسُ ‏ ‏أَوْ الزَّعْفَرَانُ فَإِنْ لَمْ يَجِدْ النَّعْلَيْنِ فَلْيَلْبَسْ الْخُفَّيْنِ وَلْيَقْطَعْهُمَا حَتَّى يَكُونَا تَحْتَ الْكَعْبَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d2495004-cc19-5c46-9474-3198fe3f008a', '5cb5e738-220a-4267-901a-841c834b5d56', '132', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُقْبَلُ صَلَاةُ مَنْ أَحْدَثَ حَتَّى يَتَوَضَّأَ قَالَ رَجُلٌ مِنْ ‏ ‏حَضْرَمَوْتَ ‏ ‏مَا الْحَدَثُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ فُسَاءٌ أَوْ ضُرَاطٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ff2422fe-49e7-5838-acc7-ac68297ed100', '5cb5e738-220a-4267-901a-841c834b5d56', '133', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏نُعَيْمٍ الْمُجْمِرِ ‏ ‏قَالَ ‏ ‏رَقِيتُ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَلَى ظَهْرِ الْمَسْجِدِ فَتَوَضَّأَ فَقَالَ إِنِّي سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أُمَّتِي يُدْعَوْنَ يَوْمَ الْقِيَامَةِ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ آثَارِ الْوُضُوءِ ‏ ‏فَمَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ ‏ ‏غُرَّتَهُ ‏ ‏فَلْيَفْعَلْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ba685733-3bc7-5d25-a99b-26d04d01bd4f', '5cb5e738-220a-4267-901a-841c834b5d56', '134', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏ح ‏ ‏وَعَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّهُ شَكَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّجُلُ الَّذِي يُخَيَّلُ إِلَيْهِ أَنَّهُ يَجِدُ الشَّيْءَ فِي الصَّلَاةِ فَقَالَ لَا ‏ ‏يَنْفَتِلْ ‏ ‏أَوْ ‏ ‏لَا يَنْصَرِفْ ‏ ‏حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0fad2f40-f7b3-5101-b0ca-ae7aae0c4d71', '5cb5e738-220a-4267-901a-841c834b5d56', '135', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏كُرَيْبٌ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَامَ حَتَّى نَفَخَ ثُمَّ صَلَّى ‏ ‏وَرُبَّمَا قَالَ اضْطَجَعَ ‏ ‏حَتَّى نَفَخَ ثُمَّ قَامَ فَصَلَّى ‏ ‏ثُمَّ ‏ ‏حَدَّثَنَا بِهِ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً بَعْدَ مَرَّةٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ بِتُّ عِنْدَ خَالَتِي ‏ ‏مَيْمُونَةَ ‏ ‏لَيْلَةً فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ فَلَمَّا كَانَ فِي بَعْضِ اللَّيْلِ قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَضَّأَ مِنْ ‏ ‏شَنٍّ ‏ ‏مُعَلَّقٍ وُضُوءًا خَفِيفًا ‏ ‏يُخَفِّفُهُ ‏ ‏عَمْرٌو ‏ ‏وَيُقَلِّلُهُ ‏ ‏وَقَامَ ‏ ‏يُصَلِّي فَتَوَضَّأْتُ نَحْوًا مِمَّا تَوَضَّأَ ثُمَّ جِئْتُ فَقُمْتُ عَنْ يَسَارِهِ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏سُفْيَانُ ‏ ‏عَنْ شِمَالِهِ ‏ ‏فَحَوَّلَنِي فَجَعَلَنِي عَنْ يَمِينِهِ ثُمَّ صَلَّى مَا شَاءَ اللَّهُ ثُمَّ اضْطَجَعَ فَنَامَ حَتَّى نَفَخَ ثُمَّ أَتَاهُ الْمُنَادِي ‏ ‏فَآذَنَهُ ‏ ‏بِالصَّلَاةِ فَقَامَ مَعَهُ إِلَى الصَّلَاةِ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏ ‏قُلْنَا ‏ ‏لِعَمْرٍو ‏ ‏إِنَّ نَاسًا يَقُولُونَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَنَامُ عَيْنُهُ وَلَا يَنَامُ قَلْبُهُ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏سَمِعْتُ ‏ ‏عُبَيْدَ بْنَ عُمَيْرٍ ‏ ‏يَقُولُ ‏ ‏رُؤْيَا الْأَنْبِيَاءِ وَحْيٌ ‏ ‏ثُمَّ قَرَأَ ‏ { ‏إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ ‏}', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e3961480-12ae-5fa8-8718-65d66696d2ae', '5cb5e738-220a-4267-901a-841c834b5d56', '136', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ ‏ ‏دَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏حَتَّى إِذَا كَانَ ‏ ‏بِالشِّعْبِ ‏ ‏نَزَلَ فَبَالَ ثُمَّ تَوَضَّأَ وَلَمْ يُسْبِغْ الْوُضُوءَ فَقُلْتُ الصَّلَاةَ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏الصَّلَاةُ أَمَامَكَ فَرَكِبَ فَلَمَّا جَاءَ ‏ ‏الْمُزْدَلِفَةَ ‏ ‏نَزَلَ فَتَوَضَّأَ فَأَسْبَغَ الْوُضُوءَ ثُمَّ أُقِيمَتْ الصَّلَاةُ فَصَلَّى الْمَغْرِبَ ثُمَّ أَنَاخَ كُلُّ إِنْسَانٍ بَعِيرَهُ فِي مَنْزِلِهِ ثُمَّ أُقِيمَتْ الْعِشَاءُ فَصَلَّى وَلَمْ يُصَلِّ بَيْنَهُمَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('276f0b38-7562-551d-b439-ef248cf6742d', '5cb5e738-220a-4267-901a-841c834b5d56', '137', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ بِلَالٍ يَعْنِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ ‏ ‏تَوَضَّأَ فَغَسَلَ وَجْهَهُ أَخَذَ ‏ ‏غَرْفَةً ‏ ‏مِنْ مَاءٍ فَمَضْمَضَ بِهَا وَاسْتَنْشَقَ ثُمَّ أَخَذَ ‏ ‏غَرْفَةً ‏ ‏مِنْ مَاءٍ فَجَعَلَ بِهَا هَكَذَا أَضَافَهَا إِلَى يَدِهِ الْأُخْرَى فَغَسَلَ بِهِمَا وَجْهَهُ ثُمَّ أَخَذَ ‏ ‏غَرْفَةً ‏ ‏مِنْ مَاءٍ فَغَسَلَ بِهَا يَدَهُ الْيُمْنَى ثُمَّ أَخَذَ ‏ ‏غَرْفَةً ‏ ‏مِنْ مَاءٍ فَغَسَلَ بِهَا يَدَهُ الْيُسْرَى ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ أَخَذَ ‏ ‏غَرْفَةً ‏ ‏مِنْ مَاءٍ فَرَشَّ عَلَى رِجْلِهِ الْيُمْنَى حَتَّى غَسَلَهَا ثُمَّ أَخَذَ ‏ ‏غَرْفَةً ‏ ‏أُخْرَى فَغَسَلَ بِهَا رِجْلَهُ ‏ ‏يَعْنِي الْيُسْرَى ثُمَّ قَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4151e3c0-0e4c-5b94-bae2-c3254f102d19', '5cb5e738-220a-4267-901a-841c834b5d56', '138', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَبْلُغُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ أَحَدَكُمْ إِذَا ‏ ‏أَتَى ‏ ‏أَهْلَهُ ‏ ‏قَالَ بِاسْمِ اللَّهِ اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ وَجَنِّبْ الشَّيْطَانَ مَا رَزَقْتَنَا فَقُضِيَ بَيْنَهُمَا وَلَدٌ لَمْ يَضُرُّهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bc3c30a2-7502-58c4-901c-14e08102adf0', '5cb5e738-220a-4267-901a-841c834b5d56', '139', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ ‏ ‏الْخَلَاءَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْخُبُثِ ‏ ‏وَالْخَبَائِثِ ‏ ‏تَابَعَهُ ‏ ‏ابْنُ عَرْعَرَةَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَقَالَ ‏ ‏غُنْدَرٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏إِذَا أَتَى الْخَلَاءَ ‏ ‏وَقَالَ ‏ ‏مُوسَى ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏إِذَا دَخَلَ ‏ ‏وَقَالَ ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏إِذَا أَرَادَ أَنْ يَدْخُلَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('320060b9-7109-5832-a585-def0bd1f5f66', '5cb5e738-220a-4267-901a-841c834b5d56', '140', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ الْخَلَاءَ فَوَضَعْتُ لَهُ وَضُوءًا قَالَ مَنْ وَضَعَ هَذَا فَأُخْبِرَ فَقَالَ ‏ ‏اللَّهُمَّ ‏ ‏فَقِّهْهُ فِي الدِّينِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8d6b4b67-b2c3-5f4f-840f-8248b8f409f8', '5cb5e738-220a-4267-901a-841c834b5d56', '141', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ ‏ ‏الْغَائِطَ ‏ ‏فَلَا يَسْتَقْبِل الْقِبْلَةَ وَلَا ‏ ‏يُوَلِّهَا ‏ ‏ظَهْرَهُ شَرِّقُوا أَوْ غَرِّبُوا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('20262f63-a335-5a4b-91cb-e9a3c02a67c1', '5cb5e738-220a-4267-901a-841c834b5d56', '142', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ يَقُولُ إِنَّ نَاسًا يَقُولُونَ إِذَا قَعَدْتَ عَلَى حَاجَتِكَ فَلَا تَسْتَقْبِلْ الْقِبْلَةَ وَلَا ‏ ‏بَيْتَ الْمَقْدِسِ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏لَقَدْ ‏ ‏ارْتَقَيْتُ ‏ ‏يَوْمًا عَلَى ظَهْرِ بَيْتٍ لَنَا فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏لَبِنَتَيْنِ ‏ ‏مُسْتَقْبِلًا ‏ ‏بَيْتَ الْمَقْدِسِ ‏ ‏لِحَاجَتِهِ وَقَالَ لَعَلَّكَ مِنْ الَّذِينَ يُصَلُّونَ عَلَى أَوْرَاكِهِمْ فَقُلْتُ لَا أَدْرِي وَاللَّهِ ‏ ‏قَالَ ‏ ‏مَالِكٌ ‏ ‏يَعْنِي الَّذِي ‏ ‏يُصَلِّي وَلَا يَرْتَفِعُ عَنْ الْأَرْضِ يَسْجُدُ وَهُوَ لَاصِقٌ بِالْأَرْضِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9251fbe6-ecf8-5c7a-bd9c-6fe57990d3c7', '5cb5e738-220a-4267-901a-841c834b5d56', '143', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ أَزْوَاجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُنَّ ‏ ‏يَخْرُجْنَ بِاللَّيْلِ إِذَا تَبَرَّزْنَ إِلَى ‏ ‏الْمَنَاصِعِ ‏ ‏وَهُوَ ‏ ‏صَعِيدٌ ‏ ‏أَفْيَحُ ‏ ‏فَكَانَ ‏ ‏عُمَرُ ‏ ‏يَقُولُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْجُبْ ‏ ‏نِسَاءَكَ فَلَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ فَخَرَجَتْ ‏ ‏سَوْدَةُ بِنْتُ زَمْعَةَ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً مِنْ اللَّيَالِي عِشَاءً وَكَانَتْ امْرَأَةً طَوِيلَةً فَنَادَاهَا ‏ ‏عُمَرُ ‏ ‏أَلَا قَدْ عَرَفْنَاكِ يَا ‏ ‏سَوْدَةُ ‏ ‏حِرْصًا عَلَى أَنْ يَنْزِلَ الْحِجَابُ فَأَنْزَلَ اللَّهُ ‏ ‏آيَةَ الْحِجَابِ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّاءُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَدْ أُذِنَ أَنْ تَخْرُجْنَ فِي حَاجَتِكُنَّ ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏يَعْنِي الْبَرَازَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7a13f98b-fc2a-5f4c-8b5b-c6bbded43291', '5cb5e738-220a-4267-901a-841c834b5d56', '144', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏وَاسِعِ بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏ارْتَقَيْتُ ‏ ‏فَوْقَ ظَهْرِ بَيْتِ ‏ ‏حَفْصَةَ ‏ ‏لِبَعْضِ حَاجَتِي فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْضِي حَاجَتَهُ مُسْتَدْبِرَ الْقِبْلَةِ مُسْتَقْبِلَ ‏ ‏الشَّأْمِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('127922de-6dd5-5ee5-9bfa-49b255e37bef', '5cb5e738-220a-4267-901a-841c834b5d56', '145', '‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏أَنَّ ‏ ‏عَمَّهُ ‏ ‏وَاسِعَ بْنَ حَبَّانَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏لَقَدْ ظَهَرْتُ ذَاتَ يَوْمٍ عَلَى ظَهْرِ بَيْتِنَا فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاعِدًا عَلَى ‏ ‏لَبِنَتَيْنِ ‏ ‏مُسْتَقْبِلَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f9f447c4-fb65-5b1f-9082-30ee80c7f648', '5cb5e738-220a-4267-901a-841c834b5d56', '146', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مُعَاذٍ وَاسْمُهُ عَطَاءُ بْنُ أَبِي مَيْمُونَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ لِحَاجَتِهِ أَجِيءُ أَنَا ‏ ‏وَغُلَامٌ ‏ ‏مَعَنَا ‏ ‏إِدَاوَةٌ ‏ ‏مِنْ مَاءٍ ‏ ‏يَعْنِي ‏ ‏يَسْتَنْجِي ‏ ‏بِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e3ce640a-3cbc-56fe-ae5e-0afdc1bcc5cd', '5cb5e738-220a-4267-901a-841c834b5d56', '147', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مُعَاذٍ هُوَ عَطَاءُ بْنُ أَبِي مَيْمُونَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ لِحَاجَتِهِ تَبِعْتُهُ أَنَا وَغُلَامٌ مِنَّا مَعَنَا ‏ ‏إِدَاوَةٌ ‏ ‏مِنْ مَاءٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5688fb32-5efa-5992-b924-ac9d97ba4365', '5cb5e738-220a-4267-901a-841c834b5d56', '148', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ الْخَلَاءَ فَأَحْمِلُ أَنَا وَغُلَامٌ ‏ ‏إِدَاوَةً ‏ ‏مِنْ مَاءٍ ‏ ‏وَعَنَزَةً ‏ ‏يَسْتَنْجِي بِالْمَاءِ ‏ ‏تَابَعَهُ ‏ ‏النَّضْرُ ‏ ‏وَشَاذَانُ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏الْعَنَزَةُ ‏ ‏عَصًا عَلَيْهِ ‏ ‏زُجٌّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('20160625-67db-5f7c-a8da-661ba518b7cd', '5cb5e738-220a-4267-901a-841c834b5d56', '149', '‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ هُوَ الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا شَرِبَ أَحَدُكُمْ فَلَا يَتَنَفَّسْ فِي الْإِنَاءِ وَإِذَا أَتَى الْخَلَاءَ فَلَا يَمَسَّ ذَكَرَهُ بِيَمِينِهِ وَلَا ‏ ‏يَتَمَسَّحْ ‏ ‏بِيَمِينِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('914191a2-fd34-5588-a6de-3cded285b688', '5cb5e738-220a-4267-901a-841c834b5d56', '150', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا بَالَ أَحَدُكُمْ فَلَا يَأْخُذَنَّ ذَكَرَهُ بِيَمِينِهِ وَلَا يَسْتَنْجِي بِيَمِينِهِ وَلَا يَتَنَفَّسْ فِي الْإِنَاءِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('92bd9825-118a-56bd-a972-fed8fd3f1f22', '5cb5e738-220a-4267-901a-841c834b5d56', '151', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدٍ الْمَكِّيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى بْنِ سَعِيدِ بْنِ عَمْرٍو الْمَكِّيُّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏اتَّبَعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَرَجَ لِحَاجَتِهِ فَكَانَ لَا يَلْتَفِتُ فَدَنَوْتُ مِنْهُ فَقَالَ ‏ ‏ابْغِنِي ‏ ‏أَحْجَارًا ‏ ‏أَسْتَنْفِضْ ‏ ‏بِهَا ‏ ‏أَوْ نَحْوَهُ ‏ ‏وَلَا تَأْتِنِي بِعَظْمٍ وَلَا ‏ ‏رَوْثٍ ‏ ‏فَأَتَيْتُهُ بِأَحْجَارٍ بِطَرَفِ ثِيَابِي فَوَضَعْتُهَا إِلَى جَنْبِهِ وَأَعْرَضْتُ عَنْهُ فَلَمَّا قَضَى أَتْبَعَهُ بِهِنَّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('01367de5-f43c-5d21-8e5b-015e09150331', '5cb5e738-220a-4267-901a-841c834b5d56', '152', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏لَيْسَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏ذَكَرَهُ وَلَكِنْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ ‏ ‏يَقُولُ ‏ ‏أَتَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْغَائِطَ ‏ ‏فَأَمَرَنِي أَنْ آتِيَهُ بِثَلَاثَةِ أَحْجَارٍ فَوَجَدْتُ حَجَرَيْنِ ‏ ‏وَالْتَمَسْتُ ‏ ‏الثَّالِثَ فَلَمْ أَجِدْهُ فَأَخَذْتُ ‏ ‏رَوْثَةً ‏ ‏فَأَتَيْتُهُ بِهَا فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى ‏ ‏الرَّوْثَةَ ‏ ‏وَقَالَ هَذَا ‏ ‏رِكْسٌ ‏ ‏وَقَالَ ‏ ‏إِبْرَاهِيمُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7770e392-4ea2-5adc-810a-b882a68cabdb', '5cb5e738-220a-4267-901a-841c834b5d56', '153', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَوَضَّأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّةً مَرَّةً ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ac818174-ee8d-5d85-adc7-597f82234e4c', '5cb5e738-220a-4267-901a-841c834b5d56', '154', '‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّتَيْنِ مَرَّتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fad36632-b4c1-534b-a117-f1af116fa38a', '5cb5e738-220a-4267-901a-841c834b5d56', '155', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ الْأُوَيْسِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَزِيدَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏أَخْبَرَهُ أَنَّهُ رَأَى ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏دَعَا بِإِنَاءٍ فَأَفْرَغَ عَلَى كَفَّيْهِ ثَلَاثَ مِرَارٍ فَغَسَلَهُمَا ثُمَّ أَدْخَلَ يَمِينَهُ فِي الْإِنَاءِ فَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثَ مِرَارٍ ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ رِجْلَيْهِ ثَلَاثَ مِرَارٍ إِلَى الْكَعْبَيْنِ ثُمَّ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏وَعَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ قَالَ ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَلَكِنْ ‏ ‏عُرْوَةُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏حُمْرَانَ ‏ ‏فَلَمَّا تَوَضَّأَ ‏ ‏عُثْمَانُ ‏ ‏قَالَ أَلَا أُحَدِّثُكُمْ حَدِيثًا لَوْلَا آيَةٌ مَا حَدَّثْتُكُمُوهُ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَتَوَضَّأُ رَجُلٌ يُحْسِنُ وُضُوءَهُ وَيُصَلِّي الصَّلَاةَ إِلَّا غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الصَّلَاةِ حَتَّى يُصَلِّيَهَا ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏الْآيَةَ ‏ { ‏إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنْ الْبَيِّنَاتِ ‏}', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('efbeaf3c-3498-5760-bc44-c433c4a42fb4', '5cb5e738-220a-4267-901a-841c834b5d56', '156', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدَانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو إِدْرِيسَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ تَوَضَّأَ ‏ ‏فَلْيَسْتَنْثِرْ ‏ ‏وَمَنْ اسْتَجْمَرَ فَلْيُوتِرْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e887baf4-e1c6-533c-825b-7b8cd329dd76', '5cb5e738-220a-4267-901a-841c834b5d56', '157', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ ثُمَّ لِيَنْثُرْ وَمَنْ اسْتَجْمَرَ فَلْيُوتِرْ وَإِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلْيَغْسِلْ يَدَهُ قَبْلَ أَنْ يُدْخِلَهَا فِي وَضُوئِهِ فَإِنَّ أَحَدَكُمْ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('98797f6c-6128-5c8e-bb85-3421f0b74300', '5cb5e738-220a-4267-901a-841c834b5d56', '158', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏تَخَلَّفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنَّا فِي سَفْرَةٍ سَافَرْنَاهَا فَأَدْرَكَنَا وَقَدْ أَرْهَقْنَا الْعَصْرَ فَجَعَلْنَا نَتَوَضَّأُ وَنَمْسَحُ عَلَى أَرْجُلِنَا فَنَادَى بِأَعْلَى صَوْتِهِ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f1610256-b92a-5c92-b5bb-9c15fcd10f62', '5cb5e738-220a-4267-901a-841c834b5d56', '159', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏أَنَّهُ رَأَى ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏دَعَا بِوَضُوءٍ فَأَفْرَغَ عَلَى يَدَيْهِ مِنْ إِنَائِهِ فَغَسَلَهُمَا ثَلَاثَ مَرَّاتٍ ثُمَّ أَدْخَلَ يَمِينَهُ فِي الْوَضُوءِ ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ وَاسْتَنْثَرَ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثًا ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ كُلَّ رِجْلٍ ثَلَاثًا ثُمَّ قَالَ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ نَحْوَ وُضُوئِي هَذَا وَقَالَ ‏ ‏مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('595b7d5a-6e54-5b49-bc57-7056994998ed', '5cb5e738-220a-4267-901a-841c834b5d56', '160', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ بْنُ أَبِي إِيَاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَكَانَ يَمُرُّ بِنَا وَالنَّاسُ يَتَوَضَّئُونَ مِنْ ‏ ‏الْمِطْهَرَةِ ‏ ‏قَالَ أَسْبِغُوا الْوُضُوءَ ‏ ‏فَإِنَّ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('71fb559a-b1ca-56c6-981c-18367e1409a9', '5cb5e738-220a-4267-901a-841c834b5d56', '161', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ جُرَيْجٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏رَأَيْتُكَ تَصْنَعُ أَرْبَعًا لَمْ أَرَ أَحَدًا مِنْ أَصْحَابِكَ يَصْنَعُهَا قَالَ وَمَا هِيَ يَا ‏ ‏ابْنَ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُكَ لَا تَمَسُّ مِنْ الْأَرْكَانِ إِلَّا الْيَمَانِيَّيْنِ وَرَأَيْتُكَ تَلْبَسُ النِّعَالَ ‏ ‏السِّبْتِيَّةَ ‏ ‏وَرَأَيْتُكَ تَصْبُغُ بِالصُّفْرَةِ وَرَأَيْتُكَ إِذَا كُنْتَ ‏ ‏بِمَكَّةَ ‏ ‏أَهَلَّ النَّاسُ إِذَا رَأَوْا الْهِلَالَ وَلَمْ تُهِلَّ أَنْتَ حَتَّى كَانَ يَوْمُ التَّرْوِيَةِ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَمَّا الْأَرْكَانُ فَإِنِّي لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمَسُّ إِلَّا الْيَمَانِيَّيْنِ وَأَمَّا النِّعَالُ ‏ ‏السِّبْتِيَّةُ ‏ ‏فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَلْبَسُ النَّعْلَ الَّتِي لَيْسَ فِيهَا شَعَرٌ وَيَتَوَضَّأُ فِيهَا فَأَنَا أُحِبُّ أَنْ أَلْبَسَهَا وَأَمَّا الصُّفْرَةُ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْبُغُ بِهَا فَأَنَا أُحِبُّ أَنْ أَصْبُغَ بِهَا وَأَمَّا الْإِهْلَالُ فَإِنِّي لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهِلُّ حَتَّى ‏ ‏تَنْبَعِثَ ‏ ‏بِهِ رَاحِلَتُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('70deacfa-31b5-5fa2-8d21-53c7d330c8b1', '5cb5e738-220a-4267-901a-841c834b5d56', '162', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أُمِّ عَطِيَّةَ ‏ ‏قَالَتْ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَهُنَّ فِي غَسْلِ ‏ ‏ابْنَتِهِ ‏ ‏ابْدَأْنَ بِمَيَامِنِهَا وَمَوَاضِعِ الْوُضُوءِ مِنْهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('72c49e56-1307-55fe-9704-55b400068a9c', '5cb5e738-220a-4267-901a-841c834b5d56', '163', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَشْعَثُ بْنُ سُلَيْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ التَّيَمُّنُ فِي تَنَعُّلِهِ ‏ ‏وَتَرَجُّلِهِ ‏ ‏وَطُهُورِهِ وَفِي شَأْنِهِ كُلِّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f0d05ff9-128b-5b2a-a041-d04b3277b4bd', '5cb5e738-220a-4267-901a-841c834b5d56', '164', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَانَتْ صَلَاةُ الْعَصْرِ ‏ ‏فَالْتَمَسَ ‏ ‏النَّاسُ الْوَضُوءَ فَلَمْ يَجِدُوهُ فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَضُوءٍ فَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ذَلِكَ الْإِنَاءِ يَدَهُ وَأَمَرَ النَّاسَ أَنْ يَتَوَضَّئُوا مِنْهُ قَالَ ‏ ‏فَرَأَيْتُ الْمَاءَ يَنْبُعُ مِنْ تَحْتِ أَصَابِعِهِ حَتَّى تَوَضَّئُوا مِنْ عِنْدِ آخِرِهِمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6809e0a6-cf7f-59fd-a831-543fb2cd2e6f', '5cb5e738-220a-4267-901a-841c834b5d56', '165', '‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَبِيدَةَ ‏ ‏عِنْدَنَا مِنْ شَعَرِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَبْنَاهُ ‏ ‏مِنْ قِبَلِ ‏ ‏أَنَسٍ ‏ ‏أَوْ مِنْ قِبَلِ أَهْلِ ‏ ‏أَنَسٍ ‏ ‏فَقَالَ ‏ ‏لَأَنْ تَكُونَ عِنْدِي شَعَرَةٌ مِنْهُ أَحَبُّ إِلَيَّ مِنْ الدُّنْيَا وَمَا فِيهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c361abe7-b2f8-5f47-83de-756370949a78', '5cb5e738-220a-4267-901a-841c834b5d56', '166', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادٌ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا حَلَقَ رَأْسَهُ كَانَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏أَوَّلَ مَنْ أَخَذَ مِنْ شَعَرِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('00ad5375-29f8-5d13-9c80-1105668b7db0', '5cb5e738-220a-4267-901a-841c834b5d56', '167', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2541ac8d-cd15-58f8-b4df-2e207750bbb3', '5cb5e738-220a-4267-901a-841c834b5d56', '168', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَجُلًا رَأَى كَلْبًا يَأْكُلُ ‏ ‏الثَّرَى ‏ ‏مِنْ الْعَطَشِ فَأَخَذَ الرَّجُلُ خُفَّهُ فَجَعَلَ يَغْرِفُ لَهُ بِهِ حَتَّى ‏ ‏أَرْوَاهُ ‏ ‏فَشَكَرَ اللَّهُ لَهُ فَأَدْخَلَهُ الْجَنَّةَ ‏ ‏وَقَالَ ‏ ‏أَحْمَدُ بْنُ شَبِيبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَمْزَةُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَتْ الْكِلَابُ تَبُولُ وَتُقْبِلُ وَتُدْبِرُ فِي الْمَسْجِدِ فِي زَمَانِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَكُونُوا يَرُشُّونَ شَيْئًا مِنْ ذَلِكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c4478242-d66e-58cc-bb0e-259cc3e259b7', '5cb5e738-220a-4267-901a-841c834b5d56', '169', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي السَّفَرِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِذَا أَرْسَلْتَ كَلْبَكَ الْمُعَلَّمَ فَقَتَلَ فَكُلْ وَإِذَا أَكَلَ فَلَا تَأْكُلْ فَإِنَّمَا أَمْسَكَهُ عَلَى نَفْسِهِ قُلْتُ أُرْسِلُ كَلْبِي فَأَجِدُ مَعَهُ كَلْبًا آخَرَ قَالَ فَلَا تَأْكُلْ فَإِنَّمَا سَمَّيْتَ عَلَى كَلْبِكَ وَلَمْ تُسَمِّ عَلَى كَلْبٍ آخَرَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5744d338-e753-5623-ba0b-88403cc707ef', '5cb5e738-220a-4267-901a-841c834b5d56', '170', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ بْنُ أَبِي إِيَاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ الْعَبْدُ فِي صَلَاةٍ مَا كَانَ فِي الْمَسْجِدِ يَنْتَظِرُ الصَّلَاةَ مَا لَمْ يُحْدِثْ فَقَالَ ‏ ‏رَجُلٌ ‏ ‏أَعْجَمِيٌّ مَا الْحَدَثُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ الصَّوْتُ ‏ ‏يَعْنِي الضَّرْطَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3b3ee254-db25-5038-a0b8-4cbee6f76f99', '5cb5e738-220a-4267-901a-841c834b5d56', '171', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْصَرِفْ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('91b93278-76f5-5885-b7af-8f3b44c8dd99', '5cb5e738-220a-4267-901a-841c834b5d56', '172', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُنْذِرٍ أَبِي يَعْلَى الْثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْحَنَفِيَّةِ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏كُنْتُ رَجُلًا ‏ ‏مَذَّاءً ‏ ‏فَاسْتَحْيَيْتُ أَنْ أَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرْتُ ‏ ‏الْمِقْدَادَ بْنَ الْأَسْوَدِ ‏ ‏فَسَأَلَهُ فَقَالَ ‏ ‏فِيهِ الْوُضُوءُ ‏ ‏وَرَوَاهُ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
